import type { AngelLong } from "./types";
export const pagesSr: AngelLong = {
  "hub": [
    { title: "Odakle dolazi numerologija", paras: ["Numerologija je stara navika da se u brojevima traži značenje. Pitagora i njegovi učenici u južnoj Italiji verovali su da je broj skriveni red koji stoji iza muzike, zvezda i ljudske duše. Jevrejski mistici davali su svakom slovu vrednost i tražili veze između reči koje imaju isti zbir. Kineska tradicija vezivala je brojeve za glasove, pa je osmica postala broj bogatstva, a četvorka se izbegavala jer zvuči kao reč za smrt. Savremena zapadna numerologija, ona koju koristi većina sajtova, dobila je svoj oblik na početku dvadesetog veka, kada su autori u Engleskoj i Americi od tih starijih niti sastavili jednostavan sistem koji polazi od datuma rođenja i imena.", "Ništa od toga nije nauka, i ne mora da bude. Ljudi se numerologijom služe onako kako se služe dobrim romanom ili dugim razgovorom s prijateljem: kao ogledalom u kome lakše primete obrasce i sebi postave bolja pitanja o sopstvenom životu."] },
    { title: "Glavni brojevi u jednom čitanju", paras: ["Celovito čitanje ima nekoliko osnovnih brojeva. Životni put, koji se računa iz datuma rođenja, opisuje glavni pravac tvog života. Broj izraza, iz punog imena upisanog u izvod iz matične knjige rođenih, pokazuje prirodne talente i način na koji izlaziš pred svet. Broj duše, iz samoglasnika u imenu, govori o onome što srce tiho priželjkuje. Broj ličnosti, iz suglasnika, opisuje prvi utisak koji ostavljaš na ljude. Broj rođendana je prosto dan tvog rođenja, mali dodatni poklon. Broj zrelosti, zbir životnog puta i broja izraza, nagoveštava u šta sazrevaš u drugoj polovini života.", "Oko njih stoje brojevi koji se tiču vremena. Lična godina pokazuje gde se nalaziš u ciklusu od devet godina, a lični dan to sužava na jedan jedini datum. Karmički dugovi, 13, 14, 16 i 19, označavaju lekcije kojima treba posvetiti dodatnu pažnju. Master brojevi, 11, 22 i 33, ne svode se dalje i nose jaču i zahtevniju verziju svog korena."] },
    { title: "Kako da počneš", paras: ["Počni od životnog puta. Najlakše se računa, a većina čitalaca se u njemu najbrže prepozna. Pročitaj njegovu stranicu polako i zapazi koje rečenice zvuče tačno, a koje ne. Posle toga izračunaj ličnu godinu i pogledaj šta tekuća godina obično donosi. Ta dva broja zajedno već ti daju i pravac i godišnje doba u kome se nalaziš.", "Kad poželiš više, upotrebi kalkulator za ime, koji ti daje broj izraza, broj duše i broj ličnosti. Uporedi ih sa životnim putem. Tamo gde se brojevi slažu, prepoznavanje je obično snažno. Tamo gde se razlikuju, često se kriju unutrašnje napetosti zbog kojih je čovek zanimljiv: tihi tragač sa imenom koje otvara vrata, slobodan duh sa srcem graditelja."] },
    { title: "Primer korak po korak", paras: ["Uzmimo datum rođenja 14. marta 1988. Mesec je 3. Dan 14 postaje 1 plus 4, što je 5. Godina 1988 postaje 1 plus 9 plus 8 plus 8, što je 26, a zatim 2 plus 6, što je 8. Saberi ta tri rezultata: 3 plus 5 plus 8 je 16, a 1 plus 6 je 7. Životni put je 7, tragač.", "Za ličnu godinu u 2026. saberi mesec i dan rođenja sa tekućom godinom: 3, pa 5, pa 2026, što postaje 10, a onda 1. Zbir je 9, pa je 2026. lična godina 9, godina završavanja i puštanja. Za jedan minut imaš osnovni pravac i temu sezone o kojoj možeš da razmisliš dok čekaš autobus."] },
    { title: "Anđeoski brojevi i svakodnevni obrasci", paras: ["Brojevi koji se ponavljaju, kao 111, 444 ili 1212, nisu deo klasične numerologije, ali su postali jedan od najpopularnijih načina na koje ljudi do nje stignu. Kad ti se neki broj stalno pojavljuje na satu, fiskalnom računu ili registarskim tablicama, može da deluje kao obeleživač u tvojoj pažnji. Naše stranice o anđeoskim brojevima čitaju svaki niz kroz njegove cifre i kroz priče ljudi koji su ga primetili, da bi sam mogao da odlučiš da li on za tebe išta znači i šta bi to bilo."] },
    { title: "Kako da mudro čitaš rezultate", paras: ["Svaki broj shvati kao opis sklonosti, a ne kao presudu. Životni put 8 nije osuđen da juri novac, kao što ni dvojka nije osuđena na stidljivost. Vrednost čitanja je u pitanjima koja otvara: gde se osećaš kao kod kuće, gde se mučiš, šta stalno odlažeš za sledeći mesec.", "Vodi beleške. Mnogi primete da čitanje dobija više smisla posle nekoliko meseci, kad se osvrnu na godinu koja je usledila. Brojevi najbolje služe kao miran saputnik u razmišljanju, a nikada kao razlog za veliku odluku koju nisi dobro promislio."] },
    { title: "Šta numerologija ne može", paras: ["Numerologija ne može da predvidi tačne događaje, da postavi dijagnozu niti da ti kaže s kim moraš da se venčaš. Ako te čeka ozbiljna odluka o novcu, zdravlju ili bezbednosti, razgovaraj s ljudima koji se u to stvarno razumeju. Brojeve koristi za ono u čemu su dobri: svež ugao iz koga gledaš sebe, nežan okvir za razmišljanje i, često, dobar razgovor s nekim ko ti je blizak."] },
  ],
  "life-path": [
    { title: "Zašto je životni put najvažniji", paras: ["Od svih brojeva u numerologiji, životni put je onaj koji ostaje s tobom od prvog do poslednjeg dana. Ime može da se promeni posle venčanja ili po sopstvenom izboru, ali datum rođenja ne može. Zato ga većina numerologa smatra stubom čitanja, središnjom linijom od koje se granaju svi ostali brojevi.", "Životni put se često opisuje kao put kojim ideš, pre nego kao osoba koja jesi. Pokazuje iskustva koja ti se stalno vraćaju, lekcije koje se ponavljaju dok ih ne naučiš i snage koje deluju prirodno čim ih upotrebiš. Dve osobe sa istim životnim putem mogu da žive potpuno različite živote i da ipak prepoznaju nešto zajedničko u obliku svojih priča."] },
    { title: "Kako se računa, korak po korak", paras: ["Zapiši ceo datum rođenja. Mesec, dan i godinu svedi na jednu cifru svaki posebno, ali zadrži 11, 22 i 33 kad god se pojave. Zatim saberi ta tri rezultata i ponovo svedi, i dalje čuvajući master brojeve.", "Evo primera. Za rođene 14. marta 1988. mesec daje 3. Dan 14 daje 1 plus 4, odnosno 5. Godina 1988 daje 1 plus 9 plus 8 plus 8, odnosno 26, pa onda 2 plus 6, odnosno 8. Sada saberi: 3 plus 5 plus 8 je 16, a 1 plus 6 je 7. Životni put je 7.", "Drugi primer pokazuje master broj. Za rođene 11. februara 1980. mesec daje 2, dan 11 ostaje 11, a godina 1980 daje 1 plus 9 plus 8 plus 0, odnosno 18, pa zatim 9. Zbir 2 plus 11 plus 9 daje 22, i taj broj se zadržava. Ova osoba ima put majstora graditelja 22, sa korenom 4."] },
    { title: "Zašto se svodi po delovima", paras: ["Neki sabiraju sve cifre iz datuma u jednom dugom nizu. Najčešće se dobije isti odgovor, ali ne uvek, a metod po delovima je onaj koji većina savremenih numerologa više voli. On poštuje tri ciklusa iz datuma, mesec, dan i godinu, i manja je verovatnoća da će sakriti master broj koji se pojavi u nekom od delova."] },
    { title: "Devet puteva ukratko", paras: ["Jedan je pionir, koji uči da vodi i da veruje sopstvenoj volji. Dva je mirotvorac, koji uči ravnotežu i tihu snagu. Tri je pripovedač, koji uči da izrazi radost, a da je ne rasipa. Četiri je graditelj, koji uči da strpljenje pravi trajne temelje. Pet je slobodan duh, koji uči da slobodu koristi mudro. Šest je negovatelj, koji uči da brine o drugima, a da pritom ne izgubi sebe. Sedam je tragač, koji uči da veruje unutrašnjoj mudrosti i da je podeli s drugima. Osam je snaga, koja uči da moć i novac koristi pošteno. Devet je humanista, koji uči da pušta i da služi nečemu većem od sebe.", "Master brojevi dodaju tri zahtevnije varijacije. Jedanaest je intuitivac, osetljiva i nadahnuta verzija dvojke. Dvadeset dva je majstor graditelj, vizionarska verzija četvorke. Trideset tri je majstor učitelj, verzija šestice puna saosećanja."] },
    { title: "Iskreno čitanje životnog puta", paras: ["Dok čitaš svoju stranicu, zapazi prvu reakciju. Ako se odmah prepoznaš, to je korisno. Ako osetiš otpor, i to može da bude korisno, jer je senka broja često baš onaj deo koji najnerado priznajemo.", "Traži obrasce kroz svoju istoriju, a ne pojedinačne događaje. Životni put 5 možda će prepoznati dug niz selidbi i promena posla. Šestica će možda primetiti koliko često prijatelji dolaze baš kod nje kad im treba pomoć. Četvorka može da vidi da su njena najveća dostignuća trajala godinama. Takvi obrasci znače više od bilo kakvog predviđanja."] },
    { title: "Životni put i odnosi", paras: ["Numerolozi često upoređuju životne puteve partnera, prijatelja ili članova porodice. Neki parovi idu lako, kao 3 i 5, oboje živahni i radoznali. Neki su izazov, kao 4 i 5, gde se red sudara sa slobodom. Kad četvorka napravi spisak za pijacu, a petica skrene do prvog novog štanda, tu se sreću dva ritma i niko nikome ništa ne radi u inat. Ipak, nijedan par nije sam po sebi dobar ili loš. Vrednost je u tome da razumeš prirodni ritam druge osobe, pa da razlike prestaneš da shvataš lično."] },
    { title: "Životni put kroz godine", paras: ["Životni put se ne menja, ali se menja tvoj odnos prema njemu. U mladosti ljudi često prvo žive senku: nestrpljenje jedinice, ugađanje dvojke. Jedinica prekida druge usred rečenice, a dvojka pristaje na sve samo da ne bi bilo svađe. U srednjim godinama mnogi počinju svesno da koriste svoje darove. Kasnije životni put često postane izvor mudrosti koja može da se prenese dalje. Kad stranicu ponovo pročitaš na svakih nekoliko godina, jednostavno vidiš koliko si daleko stigao."] },
    { title: "Česta pitanja o životnom putu", paras: ["Šta ako ne znam sat rođenja? Nije važno, koristi se samo datum. Šta ako je rođenje bilo odmah posle ponoći? Drži se datuma koji piše u izvodu. Mogu li brat i sestra da imaju isti životni put? Mogu, i često im je zabavno da upoređuju koliko ga različito žive. Da li je master broj bolji? Nije, samo je intenzivniji, sa višim zahtevima i višim nagradama."] },
    { title: "Mala vežba sa životnim putem", paras: ["Zapiši tri preokreta iz svog života, na primer selidbu, novi posao i veliku ljubav. Pored svakog napiši kakvu ti je lekciju doneo. Zatim pročitaj stranicu o svom životnom putu i vidi da li se te lekcije poklapaju sa temama broja. Ova vežba često pokaže da se kroz tvoj život odavno provlači jedna tiha nit."] },
  ],
  "master-numbers": [
    { title: "Zašto se tri broja ne svode", paras: ["Većina brojeva u numerologiji svodi se na jednu cifru. Jedanaest, dvadeset dva i trideset tri su izuzetak. Kad se neki od njih pojavi u računu, numerolozi tu staju i ostavljaju ga onakvog kakav jeste. Ideja je da udvojena cifra nosi zgusnutu i pojačanu verziju svog korena. Jedanaest je dvojka pod višim naponom, dvadeset dva je četvorka sa vizionarskom oštricom, a trideset tri je šestica podignuta na nivo služenja drugima.", "Tradicija potiče od autora s početka dvadesetog veka, koji su primetili da ljudi sa ovim brojevima često opisuju neobično intenzivne živote: snažnu intuiciju, velike ambicije, osećaj da su pozvani na nešto. To možeš da gledaš mistično ili psihološki, ali u oba slučaja master brojevi daju koristan jezik ljudima koji se istovremeno osećaju i darovito i pod pritiskom."] },
    { title: "Kako se master brojevi pojavljuju u karti", paras: ["Najčešće mesto je životni put. Za osobu rođenu 1. januara 1980. mesec daje 1, dan daje 1, a godina 1980 daje 18, pa 9. Zbir je 11, master životni put. Za rođene 11. februara 1980. rezultat je 2 plus 11 plus 9, što je 22. Za rođene 22. februara 1980. to je 2 plus 22 plus 9, što je 33.", "Master brojevi mogu da se jave i u broju izraza, duše ili ličnosti, ili kao rođendan 11, 22 ili 29, jer 29 daje 11. Svako mesto boji drugi deo života. Master broj izraza pokazuje intenzivne talente, a master broj duše opisuje srce sa snažnim osećajem misije."] },
    { title: "Život pod visokim naponom", paras: ["Ljudi koji nose master brojeve često opisuju dve faze. U prvoj im energija deluje kao previše: uznemirenost, nemir, osećaj da ne mogu da dostignu ogroman unutrašnji standard. Mnogi u tim godinama žive uglavnom kao svoj koren, kao 2, 4 ili 6. U drugoj fazi, često posle tridesete ili četrdesete, uče da taj intenzitet usmere u praksu, zanat ili neki cilj, i tada master broj počinje da sija.", "Zato numerolozi kažu da master broj mora da se zasluži. Takav broj ne deli medalje za posebnost, nego traži da polako dorasteš onome što nosiš, uz strpljenje i dovoljno odmora."] },
    { title: "Jedanaest u svakodnevnom životu", paras: ["Jedanaestice primećuju sve: raspoloženje u prostoriji, neizgovorenu napetost, suptilnu lepotu. Uđu u kancelariju i posle dva minuta znaju ko se s kim ne govori. Često rade kao savetnici, umetnici, nastavnici ili iscelitelji. Njihov izazov je preopterećenje nerava. Tiha jutra, vreme u prirodi i jasne granice prema ljudima koji mnogo traže pomažu jedanaestici da ostane nadahnuta, a ne iscrpljena."] },
    { title: "Dvadeset dva u svakodnevnom životu", paras: ["Nosioci broja dvadeset dva razmišljaju u sistemima i decenijama. Oni su ti koji osnivaju kompanije, organizuju zajednice ili projektuju zgrade koje će trajati duže od njih. Njihov izazov je težina sopstvenih očekivanja. Kad velike planove podele na sezone i proslave male korake, vizija ostaje živa, a da pritom ne smrvi onoga ko je nosi."] },
    { title: "Trideset tri u svakodnevnom životu", paras: ["Nosioci broja trideset tri osećaju tuđi bol kao svoj i često daju mnogo više nego što primaju. Cvetaju u nastavi, nezi, mentorstvu i porodičnim ulogama. Njihov izazov je samopožrtvovanje. Ko nosi ovaj broj treba da nauči da je briga o sebi deo služenja, a nikako izdaja tog služenja."] },
    { title: "Ako nemaš master broj", paras: ["Master brojevi nisu bolji od ostalih, samo su drugačiji. Mnogo izuzetnih ljudi ima jednocifren životni put. A svako se ponekad sretne sa master energijom: na lični dan 11, u godini 22 za neki projekat, u kvalitetu broja 33 dok neguje bolesnog roditelja. Čitanje o master brojevima može svakome da pomogne da razume trenutke kad život traži više nego obično."] },
    { title: "Pitanja koja postavljaju nosioci", paras: ["Zašto se osećam toliko drugačije? Zato što je ta energija intenzivna i ređa. Treba li da čitam i koren? Treba, jer koren često preciznije opisuje svakodnevicu. Da li će ovaj pritisak trajati zauvek? Obično popušta s godinama i boljim poznavanjem sebe. Može li master broj da se izgubi? Ne može, ali može da ostane neiskorišćen ako mu nikada ne nađeš praktičan kanal."] },
    { title: "Master brojevi i porodica", paras: ["Deca sa master brojevima često se opisuju kao osetljiva, intenzivna ili starija od svojih godina. Roditelji im pomažu kad tu osetljivost poštuju i ne pretvaraju je u teret očekivanja. Miran dom, vreme za igru i poverenje da će se dar razviti svojim tempom najbolja su podrška master energiji."] },
  ],
  "personal-year": [
    { title: "Godina u ciklusu od devet", paras: ["Numerologija vreme vidi kao niz ciklusa od devet godina. Svaka godina u ciklusu ima svoj karakter, kao godišnja doba u bašti. Prva godina je sadnja, peta je leto u punom jeku, kad sve buja na svoju ruku, a deveta je žetva i čišćenje njive pred sledeću setvu. Lična godina pokazuje gde si u sopstvenom ciklusu, a on nije isti kao kod nekog drugog.", "Poznavanje lične godine ne govori šta će se desiti. Daje ti raspoloženje u pozadini, kao muzika u filmu, a događaji se odvijaju ispred njega. Promena posla u ličnoj godini 1 obično deluje kao svež početak. Ista promena u ličnoj godini 9 više liči na kraj koji ti je bio potreban."] },
    { title: "Kako da izračunaš ličnu godinu", paras: ["Saberi mesec rođenja, dan rođenja i tekuću kalendarsku godinu, pošto svaki od njih svedeš na jednu cifru, a onda svedi i zbir. Master brojevi se ovde obično svode, tako da je rezultat uvek od 1 do 9.", "Primer: ako ti je rođendan 14. marta i tražiš ličnu godinu za 2026, mesec daje 3, dan 14 daje 5, a 2026 daje 2 plus 0 plus 2 plus 6, odnosno 10, pa 1. Zbir je 3 plus 5 plus 1, odnosno 9. Dakle, 2026. je lična godina 9. U 2027. biće 1, početak novog ciklusa."] },
    { title: "Kada počinje godina", paras: ["Većina numerologa menja ličnu godinu 1. januara. Neki više vole rođendan, uz obrazloženje da se lična godina okreće kad i tvoj rođendan. Praktičan pristup je da mesece između januara i rođendana shvatiš kao prelaz, u kome teme stare godine blede, a teme nove počinju da se pojavljuju."] },
    { title: "Devet godina ukratko", paras: ["Prva godina je za početke, hrabrost i nove planove. Druga usporava i traži strpljenje, partnerstvo i slušanje. Treća donosi radost, kreativnost i društvo. Četvrta je za naporan rad i temelje. Peta prodrma stvari promenama, putovanjima i slobodom. Šesta okreće pažnju ka domu, porodici i odgovornosti. Sedma poziva na razmišljanje, učenje i odmor. Osma donosi ambiciju, novac i priznanje. Deveta zatvara ciklus krajevima, darežljivošću i puštanjem.", "Nijedna od njih nije dobra ili loša. Sedma godina može da deluje sporo ako očekuješ brz uspeh, a može i lepo da te ispuni ako joj daš vreme za učenje i odmor. Peta može da izgleda haotično ako se grčevito držiš kontrole, a uzbudljivo ako sebi dozvoliš da istražuješ."] },
    { title: "Planiranje uz ličnu godinu", paras: ["Mnogi koriste ličnu godinu kao lagan alat za planiranje. U godini 1 započinju projekte. U godini 4 se posvećuju završavanju studija, otplati kredita ili renoviranju. U godini 7 planiraju pauzu ili kurseve. U godini 9 čiste kuću, zatvaraju stara poglavlja i praštaju. Rad u skladu sa raspoloženjem godine često je lakši od borbe protiv njega."] },
    { title: "Lični meseci i dani", paras: ["Unutar lične godine svaki mesec i svaki dan imaju svoj broj. Dodaj kalendarski mesec ličnoj godini i dobićeš lični mesec, a tome dodaj kalendarski dan i dobićeš lični dan. Ti manji ciklusi pomažu da vidiš zašto je jedna nedelja puna energije, a sledeća traži odmor, u okviru veće teme godine."] },
    { title: "Iskreno čitanje godine", paras: ["Na kraju svake godine pogledaj unazad. Da li se tema broja uklopila? Mnogi se iznenade koliko često se uklopi, možda zato što im je poznavanje teme pomoglo da je primete. Drugi otkriju da im je godina značila nešto drugo. I jedno i drugo je dragoceno. Kratka beleška svakog decembra pretvara numerologiju u lični zapis o rastu, umesto u gomilu predviđanja."] },
    { title: "Dve osobe, jedna kalendarska godina", paras: ["Zamisli dvoje prijatelja u istom gradu 2026. godine. Jedno je u ličnoj godini 1 i oseća snažnu želju da nešto započne: posao, selidbu, novu vezu. Drugo je u ličnoj godini 7 i ne želi ništa više od mirnih večeri, dugih šetnji i dobre knjige. Niko od njih ne greši. Njihovi ciklusi su prosto na različitim mestima, a kad to razumeš, izbegneš mnogo nesporazuma među partnerima, prijateljima i kolegama.", "Parovima često koristi da uporede lične godine. Kad je jedan partner u energičnoj godini, a drugi u sporoj, malo planiranja mnogo znači: zajedničke avanture koje ne iscrpljuju mirnijeg i vreme nasamo koje onom zauzetijem ne ostavlja osećaj da je odbijen."] },
    { title: "Česta pitanja o ličnoj godini", paras: ["Može li teška godina da se preskoči? Ne može, ali možeš da radiš s njom umesto protiv nje. Da li je lična godina 9 nesrećna? Nije, samo se u njoj stvari završavaju, što ume da bude emotivno, ali pravi mesto za svež početak godine 1. Šta ako se godina uopšte ne poklapa s mojim životom? Čitaj je kao pitanje, a ne kao opis, i vidi šta ti pomaže da primetiš. Da li je lična godina važnija od životnog puta? Nije. Životni put je drum kojim ideš, a lična godina je vreme na tom drumu, nekad sunčano, nekad kišovito."] },
    { title: "Mali godišnji ritual", paras: ["Prvog dana nove lične godine napiši broj na vrh stranice i tri reči za koje se nadaš da će ih godina doneti. Ostavi stranicu na mesto gde ćeš je naći za dvanaest meseci. Kad je ponovo pročitaš, videćeš i kako se tema godine odvijala i koliko se toga promenilo u tebi."] },
    { title: "Lična godina i naši praznici", paras: ["Kod nas godinu često mere praznici: Nova godina, Božić, Uskrs, slava, letovanje na moru. Mnogi primete da lična godina boji i te trenutke. U godini 6 praznici su porodični i topli, u godini 5 nekome se ide na put, a u godini 7 poželi se tišina. Kad znaš broj, lakše ćeš isplanirati praznik koji ti stvarno odgovara, umesto da samo ponavljaš naviku od prošle godine."] },
    { title: "Za kraj", paras: ["Svaka godina ima svoju pesmu, a kad je čuješ, lakše ti je da zaigraš."] },
  ],
  "expression-number": [
    { title: "Šta opisuje broj izraza", paras: ["Broj izraza, koji se ponekad naziva i brojem sudbine, dolazi od svakog slova punog imena upisanog pri rođenju. Dok životni put opisuje put kojim ideš, broj izraza opisuje alat koji nosiš sa sobom: prirodne talente, način na koji komuniciraš i vrstu posla u kojoj se osećaš najsposobnije. Mnogi numerolozi kažu da je životni put ono što život traži od tebe, a broj izraza ono što mu ti donosiš.", "Pošto ime obično biraju drugi, najčešće roditelji, broj izraza može da deluje kao nasledstvo. Često odražava porodične nade, kulturne korene i zvuk imena koje si čuo hiljadama puta, od učiteljice u školi do babe koja te doziva s terase. Mnogi otkriju da on opisuje kako drugi vide njihove sposobnosti, i to pre nego što ih sami prepoznaju."] },
    { title: "Kako se računa broj izraza", paras: ["Zapiši puno ime onako kako stoji u izvodu iz matične knjige rođenih, sa srednjim imenima ako ih imaš, i to latinicom. Svako slovo dobija vrednost po pitagorejskoj tabeli: A, J i S su 1; B, K i T su 2; C, L i U su 3; D, M i V su 4; E, N i W su 5; F, O i X su 6; G, P i Y su 7; H, Q i Z su 8; I i R su 9. Saberi sve vrednosti i svedi na jednu cifru, s tim što 11, 22 i 33 ostaju takvi kakvi jesu.", "Primer: uzmimo ime Maria Lang, napisano tačno ovako, dakle MARIA LANG. M je 4, A je 1, R je 9, I je 9, A je 1, zatim L je 3, A je 1, N je 5, G je 7. Zbir je 40, a 4 plus 0 je 4. Broj izraza ovog imena je 4, graditelj: praktična i pouzdana osoba, nadarena da ideje pretvara u sisteme koji rade."] },
    { title: "Ćirilica i posebna slova", paras: ["Za imena pisana ćirilicom ili posebnim slovima većina numerologa koristi latinični zapis, često onaj iz pasoša. Slova kao č, š ili ü obično se računaju kao njihovo osnovno slovo. Najvažnija je doslednost: svaki put koristi isto pisanje, najbolje ono koje najviše liči na tvoje zvanično ime. Drugačiji zapis znači druga slova, a druga slova mogu da daju i drugi zbir."] },
    { title: "Prezime posle venčanja i nadimci", paras: ["Klasični broj izraza koristi ime s rođenja, jer opisuje talente s kojima si krenuo. Može da se izračuna i prezime posle venčanja, umetničko ime ili nadimak. Numerolozi to čitaju kao drugi sloj, energiju koju preuzimaš ili pokazuješ u određenom delu života. Mnogima je zanimljivo da uporede ta dva broja i vide kako je novo ime promenilo način na koji rade ili način na koji ih drugi vide."] },
    { title: "Brojevi izraza ukratko", paras: ["Jedinica se izražava kroz inicijativu i vođstvo. Dvojka najbolje radi u partnerstvu i diplomatiji. Trojka blista u rečima, umetnosti i nastupu. Četvorka gradi sisteme i rešava praktične probleme. Petica se prilagođava, prodaje, putuje i povezuje ljude. Šestica podučava, leči i stvara lepotu u kući. Sedmica analizira, istražuje i traži istinu. Osmica organizuje, upravlja i gradi bogatstvo. Devetka nadahnjuje, služi drugima i vidi širu sliku. Jedanaest nadahnjuje kroz intuiciju, dvadeset dva gradi u velikom obimu, a trideset tri podučava sa saosećanjem."] },
    { title: "Broj izraza i životni put zajedno", paras: ["Uporedi broj izraza sa životnim putem. Kad dele istu temu, kao izraz 4 sa životnim putem 4, ljudi često opisuju jasan i usredsređen život. Kad se razlikuju, napetost može da bude kreativna. Životni put 7 sa izrazom 3 može da bude promišljena osoba koja duboke ideje iznosi kroz pisanje ili govor. Životni put 1 sa izrazom 2 može da bude vođa kome najbolje ide kroz saradnju."] },
    { title: "Broj izraza u praksi", paras: ["Mnogi pomisle na broj izraza kad razmišljaju o karijeri. On ne nameće zanimanje, ali može da istakne jake strane koje uzimaš zdravo za gotovo. Ako ti je izraz 6, možda ćeš primetiti da je svaki posao koji si voleo uključivao brigu o drugima. Ako je 5, možda je u svakoj omiljenoj ulozi bilo raznovrsnosti i kretanja. Koristi ga kao ogledalo kad biraš projekte, a ne kao pravilo."] },
    { title: "Česta pitanja o broju izraza", paras: ["Da li se broj izraza menja ako promenim ime? Broj s rođenja se ne menja, ali novo ime dodaje novi sloj. Treba li da uračunam srednje ime? Da, ako stoji u izvodu. Šta ako mi je ime dato kasnije, na primer posle usvojenja? Mnogi numerolozi koriste ime s kojim si najduže živeo, a možeš da izračunaš oba i vidiš koje ti zvuči tačnije."] },
    { title: "Mala vežba sa pohvalama", paras: ["Napiši tri stvari zbog kojih te ljudi najčešće hvale. Uporedi ih sa svojim brojem izraza i vidi koliko se poklapaju."] },
  ],
  "soul-urge-number": [
    { title: "Tihi glas srca", paras: ["Broj duše, koji se zove i želja srca, dolazi od samoglasnika u punom imenu upisanom pri rođenju. To je najprivatniji od osnovnih brojeva. Opisuje šta želiš kad niko ne gleda: vrstu ljubavi, smisla i iskustva u kojima si najviše svoj. Mnogi otkriju da im broj duše objašnjava izbore koji su iznenadili druge, kao kad neko napusti siguran posao zbog nečeg manjeg, ali smislenijeg.", "Samoglasnici su glasovi koji nose ime, dah u njemu. Numerolozi kažu da baš zato otkrivaju unutrašnji život, dok suglasnici, tvrde ivice imena, opisuju spoljašnju sliku."] },
    { title: "Kako se računa broj duše", paras: ["Uzmi celo ime s rođenja, napisano latinicom, i ostavi samo samoglasnike A, E, I, O i U. Y se računa kao samoglasnik kad tako zvuči, kao u imenima Lyn ili Mary. Svaki samoglasnik dobija pitagorejsku vrednost: A je 1, E je 5, I je 9, O je 6, U je 3, a Y je 7. Saberi ih i svedi, s tim što master brojevi ostaju netaknuti.", "Primer: u imenu MARIA LANG samoglasnici su A, I, A i A. To daje 1 plus 9 plus 1 plus 1, odnosno 12, a 1 plus 2 je 3. Broj duše ovog imena je 3. Ispod praktičnog izraza 4 krije se srce koje čezne za radošću, kreativnošću i samoizražavanjem."] },
    { title: "Brojevi duše ukratko", paras: ["Jedinica čezne za samostalnošću i za tim da u nečemu bude prva. Dvojka žudi za ljubavlju, mirom i bliskim partnerstvom. Trojka traži radost, kreativnost i publiku. Četvorka želi sigurnost i dobro sređen život, sa krovom nad glavom i računima plaćenim na vreme. Petica čezne za slobodom i avanturom. Šestica želi topao dom i osećaj da je nekome potrebna. Sedmica žudi za istinom, samoćom i dubinom. Osmica želi postignuće i kontrolu nad svojim životom. Devetka čezne da svet učini boljim, makar u svojoj ulici. Jedanaest traži duhovni smisao, dvadeset dva trajno nasleđe, a trideset tri želi da leči ljubavlju."] },
    { title: "Kad se srce i život ne slažu", paras: ["Ponekad je broj duše veoma različit od života koji živiš. Duša 5 na krutom poslu, 7 u bučnoj kući, 2 sama posle raskida. Takvi jazovi često objašnjavaju nemir kome je teško dati ime. Broj ne traži dramatičnu promenu. Poziva na male korake ka onome što srce želi: vikend izlet za peticu, sat tišine za sedmicu, nedeljni telefonski poziv prijatelju za dvojku."] },
    { title: "Broj duše u odnosima", paras: ["Partneri koji znaju broj duše jedno drugog često se bolje razumeju. Duši 6 možda treba osećaj da je potrebna i cenjena zbog svoje brige, a jedinici možda treba prostor za sopstvene odluke. Razgovor o ovim brojevima može da bude lak način da se govori o dubokim potrebama bez optuživanja, jer broj deluje kao neutralna treća strana."] },
    { title: "Vežba za razmišljanje", paras: ["Zapiši tri trenutka duboke sreće. Za svaki zabeleži šta ga je učinilo posebnim: sloboda, ljubav, lepota, postignuće, mir. Zatim uporedi spisak sa svojim brojem duše. Mnogi nađu jasnu vezu, a sama vežba je koristan podsetnik na to šta treba da čuvaš u životu."] },
    { title: "Česta pitanja o broju duše", paras: ["Zašto je Y ponekad samoglasnik? Zato što može da zvuči kao samoglasnik, a numerologija prati zvuk, ne pravopis. Šta ako jedan deo imena nema samoglasnike? Onda taj deo ne dodaje ništa broju duše, i to je u redu. Može li broj duše da bude isti kao broj izraza? Može, i to često opisuje osobu čije unutrašnje želje i spoljašnji talenti pokazuju u istom pravcu."] },
    { title: "Broj duše kroz život", paras: ["U mladosti broj duše često ostaje skriven iza želja roditelja i prijatelja, iza svega što se od tebe očekuje. Kasnije obično progovori glasnije, i mnogi najiskrenije izbore prave tek kad ga konačno poslušaju."] },
    { title: "Kako da slušaš broj duše", paras: ["Jednom mesečno se upitaj šta je tvoje srce ovog meseca najviše želelo i da li je dobilo prostora. Kratak iskren odgovor dovoljan je da se unutrašnji glas i dalje čuje."] },
    { title: "Broj duše i odluke", paras: ["Pred veliku odluku, pored liste za i protiv, upitaj se i šta bi srce izabralo. Broj duše ne treba da zameni razum i savet bliskih ljudi, ali daje glas željama koje se lako zanemare. Spisak neka ostane na stolu, samo neka i srce dobije reč. Mnogi kažu da kasnije najmanje žale za odlukama donetim i razumom i srcem."] },
    { title: "Poslednja reč", paras: ["Srce govori tiho, a broj duše pomaže da ga čuješ."] },
  ],
  "personality-number": [
    { title: "Prvi utisak", paras: ["Broj ličnosti dolazi od suglasnika u punom imenu sa rođenja. Opisuje spoljašnji sloj, ono kako izgledaš pre nego što te ljudi dobro upoznaju. Neki ga zovu ulaznim vratima kuće: pokazuje šta gosti prvo vide, a to može da bude sasvim drugačije od soba unutra. Neko pozvoni, vidi otirač i ofarbana vrata i već stvori sliku o celoj kući.", "Ovaj broj je koristan zato što mnogi nesporazumi počinju od prvog utiska. Neko sa ozbiljnom ličnošću 8 može da deluje hladno, a da je u stvari stidljiv. Vesela ličnost 3 može da izgleda bezbrižno čak i u teškim vremenima. Kad znaš broj ličnosti, lakše razumeš kako te drugi čitaju."] },
    { title: "Kako se računa broj ličnosti", paras: ["Uzmi puno ime s rođenja, napisano latinicom, i izdvoj samo suglasnike, dakle sve osim A, E, I, O i U, kao i osim Y kad zvuči kao samoglasnik. Svaki suglasnik dobija pitagorejsku vrednost; saberi ih i svedi na jednu cifru, a master brojeve zadrži.", "Primer: u imenu MARIA LANG suglasnici su M, R, L, N i G. To daje 4 plus 9 plus 3 plus 5 plus 7, odnosno 28. Zatim 2 plus 8 je 10, a 1 plus 0 je 1. Broj ličnosti ovog imena je 1. Maria na ljude ostavlja utisak samouverene, direktne i sposobne osobe, dok njena duša 3 čezne za igrom, a izraz 4 gradi polako i postojano."] },
    { title: "Brojevi ličnosti ukratko", paras: ["Jedinica izgleda samouvereno i samostalno. Dvojka deluje nežno, ljubazno i pristupačno. Trojka ostavlja šarmantan i živ utisak. Četvorka izgleda pouzdano i ozbiljno. Petica deluje energično i avanturistički. Šestica deluje toplo, odgovorno i brižno. Sedmica izgleda uzdržano, promišljeno i pomalo tajanstveno. Osmica deluje snažno, ambiciozno i uspešno. Devetka izgleda mudro, darežljivo i ponekad daleko. Jedanaest deluje osetljivo i nadahnjujuće, dvadeset dva sposobno i impresivno, a trideset tri brižno i mudro."] },
    { title: "Tri broja iz imena zajedno", paras: ["Izraz, duša i ličnost rade kao celina. Izraz je celo ime, duša je unutrašnji glas, a ličnost je spoljašnje lice. Pošto samoglasnici i suglasnici zajedno čine celo ime, duša i ličnost sabrane daju izraz pre svođenja. U primeru sa ove stranice 3 plus 1 daje 4, isti onaj broj izraza.", "Kad su sva tri broja slična, ljudi često deluju isto iznutra i spolja. Kad se razlikuju, drugi mogu da se iznenade kad im se približe i vide kakvi su. Nijedna varijanta nije bolja. Kad poznaješ svoj obrazac, lakše se predstavljaš iskreno i lakše ostaješ strpljiv kad te drugi pogrešno pročitaju."] },
    { title: "Kako da radiš sa brojem ličnosti", paras: ["Ako znaš da ličnost 7 deluje udaljeno, u novom društvu možeš da uložiš malo više truda u osmeh ili pitanje. Ako ličnost 8 deluje zastrašujuće, malo humora pomaže. Ako ličnost 2 ostavlja utisak da lako popuštaš, jedna jasna rečenica o granicama čini čuda. Broj ti opisuje masku koju drugi vide, pa možeš da je doteraš kad to poželiš, umesto da se iza nje skrivaš."] },
    { title: "Ličnost i posao", paras: ["Na razgovorima za posao, prvim sastancima i u prodaji broj ličnosti važniji je od svih drugih. Ličnost 4 često brzo stiče poverenje. Trojka brzo uspostavlja kontakt s ljudima. Jedinica daje šefovima osećaj da su našli sposobnu osobu. Kad to znaš, lakše igraš na svoje jake strane i ublažavaš utiske koji ti ne služe."] },
    { title: "Česta pitanja o broju ličnosti", paras: ["Zašto me ljudi vide drugačije nego što se osećam? Zato što se broj ličnosti često razlikuje od broja duše. Može li broj ličnosti da se promeni? Broj s rođenja ne može, ali nadimak ili izabrano ime mogu da pomere utisak koji ostavljaš. Da li je broj ličnosti manje važan? Lakši je po težini, ali u svakodnevnom druženju često je prvo na šta ljudi naiđu."] },
  ],
  "birthday-number": [
    { title: "Mali poklon iz kalendara", paras: ["Broj rođendana je najjednostavniji broj u numerologiji: to je dan u mesecu kad si rođen. Za razliku od životnog puta, ne koristi mesec i godinu. Numerolozi ga opisuju kao poseban talenat, mali poklon koji ti pomaže na životnom putu. Ako je životni put drum, broj rođendana je koristan alat u rancu.", "Pošto postoji trideset jedan mogući dan, broj rođendana je detaljniji od svedenih brojeva. Ljudi rođeni 3. i 21. u mesecu nose energiju trojke, ali svako u svojoj nijansi. Treći je čisto kreativno izražavanje, dok dvadeset prvi meša saradnju dvojke sa samostalnošću jedinice pre nego što stigne do tri."] },
    { title: "Kako se čita broj rođendana", paras: ["Počni od samog dana. Ako je jednocifren, čitaj ga direktno. Ako je dvocifren, čitaj i ceo broj i njegovo svođenje. Na primer, 14 nosi uticaj jedinice i četvorke, inicijative i reda, a svodi se na 5, slobodu i promenu. Ljudi rođeni 14. u mesecu često spajaju ljubav prema raznovrsnosti sa praktičnom crtom koja ih drži na zemlji.", "Dani 11, 22 i 29 nose master energiju. Jedanaesti i dvadeset deveti nose intuitivnu snagu broja jedanaest, a dvadeset drugi graditeljsku moć broja dvadeset dva. Ljudi rođeni tih dana često imaju snažan osećaj svrhe, ponekad i pre nego što znaju koja je to svrha."] },
    { title: "Brojevi rođendana ukratko", paras: ["Ko je rođen 1, 10, 19. ili 28. u mesecu, nosi dar za vođenje i započinjanje. Za 2, 11, 20. ili 29. to je dar za empatiju i saradnju. Za 3, 12, 21. ili 30. dar za izražavanje i radost. Za 4, 13, 22. ili 31. dar za organizovanje i gradnju. Za 5, 14. ili 23. dar za prilagođavanje i komunikaciju. Za 6, 15. ili 24. dar za brigu i odgovornost. Za 7, 16. ili 25. dar za analizu i uvid. Za 8, 17. ili 26. dar za upravljanje i ambiciju. Za 9, 18. ili 27. dar za saosećanje i viziju."] },
    { title: "Rođendan i životni put", paras: ["Broj rođendana najbolje radi zajedno sa životnim putem. Neko sa životnim putem 7, rođen 3. u mesecu, može da bude tragač koji svoja otkrića deli kroz humor i pričanje priča. Neko sa životnim putem 4, rođen 5. u mesecu, može da bude graditelj koji posao drži svežim kroz promene. Rođendan pokazuje kako prirodno prilaziš lekcijama svog puta."] },
    { title: "Proslava u duhu broja", paras: ["Neki vole da rođendan obeleže na način koji odgovara njihovom broju. Rođendan 3 traži žurku s muzikom. Sedmica možda više voli tihu šetnju i dobru knjigu. Osmica može da postavi novi cilj za narednu godinu. To je razigran način da poštuješ svoj prirodni dar i da novu godinu života počneš svojim ritmom."] },
    { title: "Česta pitanja o broju rođendana", paras: ["Šta ako je porođaj bio oko ponoći? Važi datum upisan u izvodu. Da li je broj rođendana isti kao životni put? Nije, jer životni put koristi ceo datum. Da li se broj rođendana menja? Nikada, to je najčvršći broj koji imaš. Da li je master rođendan poseban? Dodaje intenzitet, ali kao i svi master brojevi traži strpljenje i brigu."] },
    { title: "Tri priče o rođendanima", paras: ["Lea je rođena 7. u mesecu i oduvek se čudno osećala na glasnim žurkama. Kad je pročitala da rođendan 7 nosi dar za analizu i uvid, prestala je da se tera da bude duša društva i počela da pravi male večere s dugim razgovorima. Prijatelji kažu da pamte baš te večeri.", "Nikola je rođen 22. u mesecu, na dan majstora graditelja. Kao tinejdžer je stalno započinjao ogromne projekte i osećao se slomljeno kad ne uspeju. U tridesetim je naučio da planove deli na faze, i ista ta energija sada vodi malu, ali solidnu građevinsku firmu.", "Sara je rođena 15. u mesecu, što spaja 1 i 5 i svodi se na 6. U njoj se samostalnost i radoznalost sreću sa jakom željom da brine o drugima. Radi kao patronažna sestra: stalno je u pokretu, sama raspoređuje dan i odlazi ljudima u kuće, i tako na istom poslu koristi sva tri broja odjednom."] },
    { title: "Rođendan na poslu", paras: ["Broj rođendana često pokazuje veštinu koju ljudi kod tebe najviše hvale, čak i kad je uzimaš zdravo za gotovo. Ako kolege uvek od tebe traže da organizuješ događaje, možda ti je rođendan 4 ili 8. Ako ti donose svoje probleme, možda je 2 ili 6. Ako traže da baš ti održiš prezentaciju, možda je 3 ili 5. Kad to primetiš, lakše biraš uloge koje deluju prirodno, a ne nametnuto."] },
    { title: "Rođendan u porodici", paras: ["Roditelji ponekad koriste broj rođendana da bolje razumeju decu. Dete rođeno 5. u mesecu možda ima veću potrebu za kretanjem i raznovrsnošću od braće i sestara. Detetu rođenom 7. možda posle škole treba tišina. Upotrebljen nežno, broj podseća da svako dete ima prirodan ritam koji vredi poštovati."] },
    { title: "Mali rođendanski ritual", paras: ["Na sledeći rođendan napiši broj rođendana na karticu, a uz njega jedan način na koji želiš da koristiš njegov dar u godini koja dolazi. Čuvaj karticu u novčaniku. Svaki put kad je vidiš, podsetiće te na talenat s kojim si došao na svet i na obećanje da ćeš ga koristiti."] },
    { title: "Rođendan i naši običaji", paras: ["Kod nas se rođendan obično slavi uz tortu, prijatelje i porodicu, a u mnogim kućama veći dan u godini je slava, koja se prenosi u porodici i okuplja rodbinu i komšije. Numerologija gleda samo datum rođenja, ali slava može da bude lep povod da se razmisli i o broju izraza, jer i slava i prezime dolaze od porodice. Tako dva dana u godini postaju dva mala pregleda: jedan za talenat s kojim si došao na svet, drugi za ime koje nosiš.", "Ako te deca pitaju šta znači njihov rođendan, reci im broj kao malu tajnu moć: dar da vode, da zasmeju, da brinu o drugima. Deca vole takve priče i često rastu u njima."] },
    { title: "Jedna misao na kraju", paras: ["Svaki dan u kalendaru nosi svoj poklon."] },
  ],
  "maturity-number": [
    { title: "U šta izrastaš", paras: ["Broj zrelosti, koji neki zovu i brojem ostvarenja, opisuje osobu u koju polako izrastaš u drugoj polovini života. Dobija se kad sabereš životni put i broj izraza. Numerolozi kažu da njegov uticaj raste sporo i da se često jasnije vidi tek oko trideset pete ili četrdesete godine, kad se ono što te je životni put naučio spoji sa talentima koje nosiš u imenu.", "Mnogi o broju zrelosti govore kao o skrivenom cilju. Tokom mladosti radi tiho, negde u pozadini, i retko ga primetiš. Kasnije se život često sam okrene prema njemu, kroz promenu posla, novu strast ili drugačiji osećaj za to šta ti je u životu važno."] },
    { title: "Kako se računa", paras: ["Životni put nađi iz datuma rođenja, a broj izraza iz punog imena i prezimena kakvi stoje u izvodu iz matične knjige rođenih. Saberi ta dva broja i svedi zbir na jednu cifru, s tim što 11, 22 i 33 ostaju kakvi jesu.", "Primer: osoba rođena 14. marta 1988. ima životni put 7. Ako se zove Maria Lang, broj izraza joj je 4. Sedam i četiri daju 11, a to je master broj, pa se dalje ne svodi. Njen broj zrelosti je 11. Tragalac sa talentima graditelja može da izraste u nadahnutog vodiča, u nekoga kod koga se tiho učenje i praktične veštine spoje u dar da drugima pomogne da stvari vide jasnije."] },
    { title: "Brojevi zrelosti ukratko", paras: ["Zrelost 1 vodi u samostalnost i vođstvo. Zrelost 2 vodi u partnerstvo i diplomatiju, u umeće da se dvoje dogovore. Sa zrelošću 3 dolazi radosno izražavanje, a sa 4 stabilnost i majstorstvo u zanatu. Zrelost 5 sazreva u slobodu i širok pogled na život, zrelost 6 u brigu o porodici i zajednici. Uz zrelost 7 rastu mudrost i duhovna dubina, uz 8 autoritet i materijalni uspeh, uz 9 velikodušnost i služenje drugima. Master brojevi idu još dalje: 11 sazreva u nadahnuto vođstvo, 22 u gradnju velikih razmera, a 33 u podučavanje puno saosećanja."] },
    { title: "Zašto zrelost traži vreme", paras: ["Broj zrelosti ne stiže odjednom. Raste zajedno sa iskustvom, kako učiš iz onoga što ti se dešava. U mladosti ljudi često idu za tuđim očekivanjima: roditelji znaju koji je fakultet dobar, okolina zna kad je vreme za stan i decu. U srednjim godinama mnogi počnu da biraju za sebe, i tada se broj zrelosti obično pomoli. Osoba sa zrelošću 8 može da otvori svoju firmu tek u četrdeset petoj. Šestica može da otkrije ljubav prema podučavanju tek kad joj deca odrastu."] },
    { title: "Kako da radiš sa brojem zrelosti", paras: ["Čitaj broj zrelosti kao pravac u kome rasteš. Ako se mnogo razlikuje od tvog životnog puta, pitaj se koji bi te mali koraci približili njemu. Životni put 7 sa zrelošću 3 može da počne da deli svoje ideje sa ljudima, makar i u malom krugu. Petica sa zrelošću 4 može da sagradi stabilnu osnovu za svoje avanture. Broj pokazuje šta ti kasnije u životu donosi duboko zadovoljstvo, pa možeš da se pripremiš za to bez žurbe."] },
    { title: "Zrelost i životna doba", paras: ["Mnogi primećuju prelom oko četrdesete, kad se prioriteti pomere i stvari koje su donedavno bile važne odjednom izblede. Broj zrelosti tom pomeranju daje pravac. Ume da uteši saznanje da se nemir u tim godinama može čitati kao rast, kao izrastanje u potpuniju verziju sebe, pre nego kao kriza. Ako broj pročitaš ponovo na svakih nekoliko godina, videćeš kako postepeno oživljava."] },
    { title: "Česta pitanja o zrelosti", paras: ["Da li mi treba puno ime sa rođenja? Treba, jer je broj izraza deo računice. Mogu li mladi da koriste broj zrelosti? Mogu, kao dugoročni nagoveštaj, ali on još ne opisuje ono što žive danas. Šta ako mi je zrelost master broj? To nagoveštava poziv koji sazreva kasno, uz snažan osećaj svrhe u poznijim godinama."] },
    { title: "Mala vežba", paras: ["Napiši kako zamišljaš jedno obično jutro u svojoj šezdesetoj godini: gde se budiš, ko je pored tebe, šta radiš posle prve kafe. Zatim uporedi tu sliku sa svojim brojem zrelosti i vidi koje se reči poklapaju."] },
  ],
  "karmic-debt": [
    { title: "Šta znači karmički dug u numerologiji", paras: ["Karmički dugovi su četiri dvocifrena zbira, 13, 14, 16 i 19, kojima numerolozi posvećuju posebnu pažnju. Ideja potiče iz verovanja u reinkarnaciju: duša može da nosi nedovršene lekcije iz ranijih života, a one se u ovom javljaju kao teškoće koje se ponavljaju. Ne moraš da veruješ u prošle živote da bi ti ovaj pojam bio od koristi. Psihološki gledano, svaki karmički broj opisuje obrazac koji se vraća sve dok se s njim ne suočiš iskreno i uz trud.", "Reč dug može da zvuči teško, naročito onome ko svakog meseca plaća ratu za kredit, ali je numerolozi obično izgovaraju s nadom. Dug može da se vrati. Svaki karmički broj dolazi sa jasnom lekcijom, a ljudi koji rade na njoj često kažu da im je kasnije u životu postala izvor najveće snage."] },
    { title: "Gde se pojavljuje karmički dug", paras: ["Karmički dug se javlja kad se jedan od ovih zbirova pojavi neposredno pre poslednjeg svođenja nekog osnovnog broja. Ako ti životni put daje 16 pre nego što se svede na 7, nosiš karmički dug 16 na životnom putu 7. Isto važi za broj izraza, broj duše i broj ličnosti. Rođendan je najdirektniji slučaj: ko je rođen trinaestog, četrnaestog, šesnaestog ili devetnaestog u mesecu, nosi taj karmički broj.", "Primer: osoba rođena 16. maja 1990. ima rođendan 16, pa se karmički dug 16 javlja direktno. Životni put pokazuje još jedan. Mesec daje 5, dan 16 daje 7, a godina 1990 daje 19, pa 10, pa 1. Zbir 5 plus 7 plus 1 je 13, što se svodi na 4. Dakle, ova osoba ide životnim putem 4 koji prolazi kroz 13, dug truda, a povrh toga ima i rođendan 16. Neki numerolozi beleže i 19 skriveno u godini, ali većina broji samo zbirove koji stoje neposredno pre osnovnog broja."] },
    { title: "Četiri broja ukratko", paras: ["Trinaest se svodi na četiri i zove se dug truda. Lekcija mu je strpljenje, disciplina i završavanje započetog, posle starog obrasca bežanja od teškog rada. Četrnaest se svodi na pet i nosi dug slobode: uči te umerenosti i odgovornom korišćenju slobode, posle starog obrasca preterivanja. Šesnaest se svodi na sedam i predstavlja dug ega. Njegova lekcija su skromnost i iskreno preispitivanje sebe, što se često nauči kroz iznenadne padove gordosti. Devetnaest se svodi na jedan i to je dug moći. Od tebe traži samostalnost bez sebičnosti i učenje kako da prihvatiš pomoć."] },
    { title: "Život sa karmičkim brojem", paras: ["Ljudi sa karmičkim dugom često pričaju kako im se isti problemi vraćaju u novom ruhu. Trinaestica stalno nailazi na prepreke koje traže strpljenje. Četrnaesticu stalno sačekuju iskušenja da preteruje. Šesnaestica stalno doživljava nagle promene koje joj spuštaju gordost. Devetnaestica se stalno nađe sama, dok ne nauči da zatraži podršku.", "Kad prepoznaš obrazac, pola posla je već urađeno. Čim znaš lekciju, svako ponavljanje postaje prilika da odgovoriš drugačije, i krug polako popušta."] },
    { title: "Karmički dug nije kazna", paras: ["Lako je karmičke brojeve čitati kao kletvu. Većina numerologa kaže suprotno: karmički broj pokazuje oblast u kojoj je rast posebno bogat. Trinaestice često postanu najpouzdaniji ljudi u svom društvu, oni koje zoveš kad nešto mora da bude gotovo. Četrnaestice često postanu mudri savetnici za ravnotežu i slobodu. Šesnaestice mogu da postanu duboko skromne i duhovne osobe. Devetnaestice mogu da izrastu u snažne vođe koji pomažu drugima da ojačaju."] },
    { title: "Kako da radiš sa karmičkim dugom", paras: ["Imenuj lekciju jasno i zapiši je negde gde ćeš je viđati, recimo na vratima frižidera ili na poleđini sveske. Izaberi jednu malu dnevnu naviku koja je podržava. Za 13 to može da bude završavanje jednog zadatka pre nego što počneš drugi, za 14 jednostavna granica za trošenje ili vreme pred ekranom, za 16 kratko večernje razmišljanje, za 19 traženje pomoći jednom nedeljno. Tokom meseci ovi sitni postupci menjaju obrazac više nego bilo koja velika odluka."] },
    { title: "Česta pitanja o karmičkom dugu", paras: ["Može li neko da ima više od jednog karmičkog broja? Može, u različitim delovima karte. Hoće li trajati zauvek? Broj ostaje, ali mu težina obično popušta kako savladavaš lekciju. Da li je karmički dug isto što i loša sreća? Nije. On opisuje lekciju, a sudbinu ne određuje. Treba li deci pričati o karmičkim brojevima? Ako već pričaš, neka to bude nežno, kao opis snage koja raste vežbanjem."] },
    { title: "Karmički brojevi u odnosima", paras: ["Kad oboje u paru nose karmičke brojeve, njihove lekcije se često ukrste. Četrnaestica koja se bori sa granicama može da se zagleda u trinaesticu koja voli red, i oboje mogu da uče jedno od drugog: četrnaestica dobija stabilnost, trinaestica uči da se opusti. Otvoren razgovor o ovim obrascima, bez optuživanja, može staro trenje da pretvori u zajednički rast."] },
    { title: "Kratko razmišljanje", paras: ["Zapiši lekciju svog karmičkog broja na karticu. Jednom mesečno zabeleži jedan trenutak kad te je stari obrazac sačekao i kakav je bio tvoj odgovor. Za godinu dana beleške će pokazati kako se dug polako vraća."] },
    { title: "Dve priče", paras: ["Marko je rođen trinaestog i u dvadesetim je napuštao poslove čim bi mu dosadili. U tridesetim se obavezao na jedan zanat i ostao u njemu pet godina. Danas vodi radionicu i kaže da se strpljenje pokazalo kao njegov skriveni talenat.", "Tinin broj izraza prolazi kroz 14. Volela je žurke, putovanja i trošenje, sve dok je dugovi nisu naterali da stane. Umerenost joj život nije smanjila, samo je slobodu učinila održivom."] },
    { title: "Rečenica za pamćenje", paras: ["Dug koji si jasno imenovao već je napola vraćen."] },
    { title: "Karmički dug i porodični obrasci", paras: ["Mnogi primećuju da lekcija njihovog karmičkog broja liči na obrazac koji je postojao i kod roditelja ili kod babe i dede: dugovi koji se ponavljaju, gordost zbog koje braća godinama ne razgovaraju, bežanje od teškog rada. Možeš to zvati karmom, možeš porodičnim nasleđem, broj ti u oba slučaja nudi priliku da taj krug prekineš. Svaka nova generacija koja savlada lekciju ostavlja lakši teret onima koji dolaze."] },
  ],
  "personal-day": [
    { title: "Broj za svaki dan", paras: ["Lični dan je najmanji ciklus u numerologiji. Unutar devetogodišnjeg ciklusa i ličnog meseca svaki dan nosi svoj broj od 1 do 9 i daje mu laganu temu: dobar trenutak da nešto počneš, da se odmoriš, da popričaš, da završiš. Mnogi ga pogledaju ujutru, uz kafu, kao kratku vremensku prognozu za raspoloženje tog dana.", "Pošto se menja svakog dana, lični dan je broj koji se najlakše proverava. Za nekoliko nedelja sam ćeš videti da li se teme poklapaju sa onim što ti se dešava."] },
    { title: "Računica korak po korak", paras: ["Prvo nađi ličnu godinu: saberi mesec i dan rođenja sa tekućom godinom, a svako od tih brojeva pre toga svedi na jednu cifru. Zatim dodaj tekući mesec i dobijaš lični mesec, pa dodaj tekući dan i dobijaš lični dan, s tim što na svakom koraku zbir svodiš.", "Primer: osoba rođena 14. marta ima u 2026. godini ličnu godinu 9. Na dan 14. oktobra 2026. godine mesec 10 se svodi na 1, a dan 14 na 5. Devet plus jedan plus pet daje 15, a 1 plus 5 daje 6. Za tu osobu to je lični dan 6, dobar dan za dom, porodicu i brigu o svojima."] },
    { title: "Devet dana ukratko", paras: ["Dan 1 je za početke, odluke i preuzimanje inicijative. Dan 2 prija saradnji, strpljenju i nežnim razgovorima. Dan 3 je za društvo, kreativnost i zabavu. Dan 4 je za praktične poslove, papire i redovan rad, recimo za odlazak u opštinu ili banku. Dan 5 donosi promene, kretanje i iznenađenja. Dan 6 pripada domu, porodici i pomaganju drugima. Dan 7 odgovara odmoru, učenju i razmišljanju. Dan 8 je naklonjen poslu, novcu i ambiciji. Dan 9 služi za završavanje, čišćenje i puštanje onoga što je prošlo."] },
    { title: "Kako da dobro iskoristiš lični dan", paras: ["Planiraj bez pritiska. Ako ti važan sastanak padne na dan 7, dobro se pripremi i više slušaj nego što pričaš. Ako hoćeš da pokreneš neki projekat, dan 1 daje prijatan podsticaj. Kad dođe dan 9, možda je pravo vreme da očistiš sanduče sa mejlovima i zatvoriš stare stvari. Lični dan je blag predlog i ne traži da ga pratiš kao raspored časova."] },
    { title: "Lični dani i odnosi", paras: ["Dvoje ljudi može da ima sasvim različite dane na isti datum. Jedno može da bude u danu 3 i da želi društvo i smeh, a drugo u danu 7, kad mu treba tišina. Kad to znaš, lakše izbegneš sitne svađe. Kratko pitanje ujutru, „kakav ti je danas dan”, može da postane razigrana navika u paru i u porodici."] },
    { title: "Jednostavna dnevna navika", paras: ["Svako jutro zapiši datum i broj ličnog dana u svesku, uz jednu reč o tome kako želiš da ga provedeš. Uveče dodaj jednu reč o tome kako je stvarno prošao. Posle mesec dana pročitaj svesku od početka. Videćeš obrasce u svojoj energiji i koliko se dnevne teme uklapaju u tvoj život."] },
    { title: "Česta pitanja o ličnom danu", paras: ["Da li se master brojevi računaju kod ličnih dana? Većina numerologa ih svodi, mada neki dane 11 i 22 beleže kao naročito intuitivne ili produktivne. Šta ako broj dana ne odgovara mojim planovima? Uradi ono što moraš, broj samo predlaže stav. Da li je dan 9 baksuzan? Nije, dobar je za završetke i velikodušnost. Mogu li da koristim lični dan za velike odluke? Koristi ga kao vodič za raspoloženje, nikad kao jedini razlog."] },
    { title: "Lični dani na poslu", paras: ["Neki planiraju radnu nedelju po ličnim danima: pozive i prezentacije za dane 1 i 8, timski rad za dan 2, administraciju za dan 4, posao koji traži punu koncentraciju za dan 7. Čak i mala promena, kao kad teške mejlove ostaviš za dan 4, može da olakša posao. Neka to ostane razigrano i fleksibilno, a prave rokove ne pomeraj zbog broja."] },
    { title: "Tri dana u jednoj nedelji", paras: ["Ana je primetila da joj je ponedeljak dan 7, sreda dan 9, a petak dan 2. Ponedeljak je iskoristila za tiho planiranje, sredu za čišćenje mejlova i starih zadataka, a petak za dug ručak s koleginicom koju je zapostavila. Ništa čudesno se nije desilo, ali je nedelja prošla neobično glatko. Navika joj je ostala, a brojevi su joj sitni znaci kako da zadatke uskladi sa svojom energijom."] },
    { title: "Lični dani i deca", paras: ["Porodice ponekad lične dane pretvore u igru za doručkom: čiji je danas dan za avanturu, čiji za odmor, čiji za pomaganje? Deca vole da imaju svoj broj, a to može da otvori lake razgovore o raspoloženjima i potrebama."] },
    { title: "Jedna rečenica za usput", paras: ["Svaki dan ima svoju melodiju: prvo je poslušaj, pa onda biraj korake."] },
    { title: "Lični dan i naše navike", paras: ["Kod nas se mnogo toga dogovara uz kafu, a važni razgovori često čekaju vikend, praznik ili slavu, kad se svi nađu za istim stolom. Lični dan može da pomogne da izabereš pravi trenutak: težak razgovor u danu 2, kafu sa starim prijateljem u danu 3, račune i papire u danu 4. Sve to je više mali savet nego pravilo, a dan čini mirnijim i prijatnijim."] },
    { title: "Misao za sutra", paras: ["Sutra ujutru izračunaj lični dan i izaberi jednu stvar koja najbolje odgovara njegovoj temi. Uveče proveri da li ti je dan bio lakši."] },
    { title: "Kratko na kraju", paras: ["Mali dani grade velike godine, jedan po jedan."] },
  ],
  "karmic-debt/13": [
    { title: "Dug truda", paras: ["Trinaest je karmički broj koji se najviše vezuje za rad. Prema starim numerolozima, označava dušu koja je u nekom ranijem životu izbegavala teške zadatke ili svoj deo posla ostavljala drugima. U ovom životu stare prečice više ne prolaze. Planovi stanu, projekti se raspadnu čim se požuri, a napredak dolazi samo uz strpljenje i stalan trud. Možeš to da čitaš kao karmu, a možeš i prosto kao temperament koji najbolje uči kad stvari radi polako i temeljno.", "Trinaest se svodi na četiri, broj graditelja, i tu je ključ. Dug se vraća gradnjom: jedan pošten zadatak za drugim, dan za danom, bez traženja brzog puta do cilja. Ljudi koji nose 13 često otkriju da im disciplina, nekad teret, vremenom postane razlog za ponos."] },
    { title: "Kako se 13 vidi u svakodnevici", paras: ["Ljudi sa 13 često imaju osećaj da drugi stižu brže i uz manje muke. Počnu mnogo toga s oduševljenjem, pa izgube volju čim dođe dosadan deo. Dešava im se da ih obaveze pritisnu, pa odlažu sve dok im rok ne zakuca na vrata. Ponekad se javi i gorčina: zašto je kod mene sve teže?", "Numerologija na to odgovara blago. Teže ti ide zato što ova lekcija traži dubinu, a s tobom je sve u redu. Svaki put kad nešto završiš do kraja, stara priča malo popusti. Trinaest ume da se pokaže i kao rasuta energija, previše interesovanja i premalo fokusa, pa četvorka u njemu traži jednu jasnu strukturu: raspored, plan, jedan zanat koji ćeš savladati."] },
    { title: "Tri priče o broju 13", paras: ["Jedna studentkinja rođena trinaestog tri puta je menjala fakultet, uvek na drugoj godini, kad bi predmeti postali teški. Četvrti put je sebi postavila prosto pravilo: svakog dana po sat učenja, bez izuzetka, i subotom i za praznike. Diplomirala je s visokim prosekom i danas kaže da joj je to pravilo promenilo život.", "Jedan stolar je nasledio zanat od oca, ali je godinama radio brzo i jeftino. Porudžbine su dolazile i odlazile. Kad je počeo da radi sporije i preciznije, cene su mu porasle, a mušterije su počele da se vraćaju i da ga preporučuju komšijama.", "Jedna majka troje dece, sa životnim putem koji prolazi kroz 13, godinama je pokušavala da sredi stan za jedan vikend i uvek bi odustala. Kad je počela sa po jednom fiokom dnevno, za dva meseca je sve bilo na svom mestu, a ona je prvi put osetila mir među svojim zidovima."] },
    { title: "Darovi broja 13", paras: ["Kad se lekcija prihvati, 13 postaje izvor velike snage. Ovi ljudi znaju da naprave ono što traje: firme, domove, veštine, prijateljstva. Imaju praktičnu inteligenciju i vide korake koje drugi preskaču. Uspeh im često dolazi kasnije, ali duže traje, jer je izgrađen na čvrstoj osnovi. Ista energija koja se nekad bunila protiv truda postaje dar za majstorstvo."] },
    { title: "Senke broja 13", paras: ["Senka broja 13 je lenjost, ali se ona češće krije iza nečeg drugog: straha od neuspeha, perfekcionizma, osećaja da trud nema smisla. Druga senka je suprotna krajnost, rad bez odmora, kao da vrednost mora da se dokaže iscrpljenošću. Ravnoteža leži u stabilnom ritmu, dok herojski napori samo troše snagu."] },
    { title: "Šta da vežbaš sa 13", paras: ["Podeli svaki veliki cilj na male korake i zapiši ih. Radi u kratkim, redovnim periodima umesto u retkim maratonima. Završi jednu stvar pre nego što počneš novu. Proslavi i male završene zadatke, makar kafom u miru. Kad zapneš, pitaj se koji je najmanji sledeći korak i napravi ga još danas."] },
    { title: "Trinaest u ljubavi", paras: ["U vezama 13 uči da se i ljubav gradi. Prva iskra je laka, ali duga veza traži svakodnevnu brigu: razgovore, sitne pažnje, održana obećanja, pošten deo kućnih poslova. Ko živi sa trinaesticom često ceni njenu vernost, naročito kad ona nauči da bude prisutna i u običnim danima."] },
    { title: "Trinaest na poslu i sa novcem", paras: ["U karijeri 13 najbolje ide tamo gde se napredak jasno vidi: zanati, inženjerstvo, finansije, medicina, svaki posao u kome veština raste sa godinama. Kod novca je lekcija štednja i strpljenje. Brze šeme retko uspevaju, a redovno odvajanje malih suma, makar nekoliko hiljada dinara mesečno, s vremenom daje osećaj sigurnosti."] },
    { title: "Pitanja za razmišljanje", paras: ["Gde u svom životu tražim prečicu? Koji zadatak odlažem već nedeljama? Šta bi izgradila jedna strpljiva osoba i mogu li da počnem s tim još danas? Kad sam poslednji put nešto završio do kraja i kako mi je tada bilo?"] },
    { title: "Gde stoji 13 u karti", paras: ["Mesto na kome se 13 pojavi daje mu posebnu boju. Kao rođendan, ono je svakodnevni saputnik, dar za rad koji čeka da ga iskoristiš. Na životnom putu oblikuje ceo pravac života, pa strpljenje postaje glavna tema. U broju izraza često se vidi u karijeri: prvo moraš da savladaš zanat, pa tek onda stiže uspeh. U broju duše opisuje srce koje potajno čezne za zadovoljstvom završenog posla, čak i kad razum traži prečice."] },
    { title: "Trinaest u porodici", paras: ["Deci rođenoj trinaestog često treba pomoć da nauče da završavaju zadatke. Najbolje deluju nežne rutine, mali ciljevi i pohvale za trud, više nego za talenat. Odrasli sa 13 mogu da porodični život pretvore u zajedničku vežbu: po jedan kućni projekat, završen zajedno, svima daje osećaj uspeha i drži dom stabilnim."] },
    { title: "Tegla završenih poslova", paras: ["Nedeljom uveče zapiši jednu stvar koju si u proteklih sedam dana priveo kraju, ma koliko bila sitna. Ceduljice stavljaj u teglu. U teškim danima pročitaj nekoliko njih. Tegla postaje vidljiv dokaz da se trud sabira i smiruje stari strah da napor nikud ne vodi."] },
    { title: "Zrno po zrno", paras: ["Kod nas se kaže: zrno po zrno pogača, kamen po kamen palača. Naše bake su to znale bez numerologije: zimnica se pravi teglu po teglu, zid se zida red po red. Trinaest nosi istu mudrost. Brzina tu malo znači, a mnogo znači to da svakog dana napraviš po jedan korak."] },
    { title: "Trinaest uz druge brojeve", paras: ["U društvu drugih brojeva lekcija 13 dobija nove nijanse. Sa životnim putem 1 trud se spaja sa inicijativom: počinjanje ti ide lako, pa učiš i da završavaš. Sa 3 stvaralačka energija traži disciplinu da bi od nje nastalo delo. Sa 7 dugo razmišljanje treba da se pretvori u praktične korake. Kakva god da je kombinacija, ostaje isto pitanje: šta mogu da završim danas?"] },
    { title: "Za kraj", paras: ["Trinaest nagrađuje upornog. Kad ti put izgleda dug, seti se da su svaki ozbiljan zanat, svaki dom koji traje i svako ime kome ljudi veruju izgrađeni na isti način: jedan običan dan za drugim, s pažnjom, dok se obični dani ne saberu u nešto izuzetno. Ta spora aritmetika je pravi dar ovog broja i nikad ne prestaje da vraća."] },
  ],
  "karmic-debt/14": [
    { title: "Dug slobode", paras: ["Karmički broj četrnaest vrti se oko slobode i umerenosti. Tradicija ga vezuje za dušu koja je u ranijem životu zloupotrebila slobodu, kroz preterivanje, zavisnosti ili bežanje od odgovornosti. U ovom životu čula su jaka, radoznalost velika, a život brzo ispostavi račun kad preteraš. Psihološki, 14 opisuje nemiran temperament koji uči da prava sloboda traži granice.", "Četrnaest se svodi na pet, broj promene i avanture. Lekcija ne traži da se avanture odrekneš. Traži da je živiš svesno, sa nekoliko izabranih granica od kojih tvoji izlasci u svet postaju i bogatiji i bezbedniji."] },
    { title: "Nemir u običnom danu", paras: ["Ljudima sa 14 brzo dosadi, vole promene, putovanja, nove ljude i nove ideje. Teško im je da ostanu na jednom mestu, u istom poslu ili istoj rutini. Kad im se nešto dopadne, lako preteraju: s hranom, s parama, s provodom, s poslom. Život ih onda naglo spusti na zemlju, kroz bolest, dug ili izgubljenu priliku.", "Takvi padovi su povratna informacija, ma koliko podsećali na kaznu. Svaki put kad izabereš meru umesto viška, učiš da pametno koristiš svoju energiju. Četrnaest ume da donese i strah od obaveza, mada se obaveza i sloboda ne isključuju: sa stabilnom osnovom možeš da istražuješ a da ne staviš sve na kocku."] },
    { title: "Tri priče o broju 14", paras: ["Milica je rođena četrnaestog, radila je kao novinarka i menjala redakciju svake godine, svaki put od nule. Kad je našla mesto koje joj daje i putovanja i stalan tim, ostala je sedam godina i postala urednica.", "Kuvar Dejan je hteo sve da proba: nove restorane, nove gradove, nove recepte. Trošio je više nego što je zarađivao. Kad je sebi odredio mesečni budžet za avanture, zadovoljstva je zadržao, a dugovi su nestali.", "Nikola, otac dvoje dece, sa životnim putem koji se svodi preko 14, godinama je živeo od vikenda do vikenda. Kad je sa decom napravio plan za po jedan mali izlet svakog meseca, do vikendice ili u grad u kome nikad nisu bili, njegova želja za novim postala je zajednička radost umesto bega."] },
    { title: "Darovi broja 14", paras: ["Kad nauči meru, 14 ima šta da pokloni: prilagodljivost, hrabrost, šarm i sposobnost da svet razume kroz iskustvo. Ovi ljudi su odlični sagovornici, putnici, prodavci, umetnici. Unose energiju u prostoriju i hrabre druge da probaju nešto novo. Iskustvo sa viškom često ih učini blagim prema tuđim mukama."] },
    { title: "Senke broja 14", paras: ["Preterivanje u svim oblicima, to je senka broja 14: zavisnosti, impulsivne kupovine, nagle odluke, bežanje od obaveza. Uz njega ide i strah od vezivanja, pa se iz veze ili sa posla beži baš kad stvari postanu ozbiljne. Pomažu prijateljske granice koje čovek sam izabere, dok stroga disciplina obično brzo pukne."] },
    { title: "Vežbe za 14", paras: ["Pred veliku odluku sačekaj jedan dan. Postavi jasne granice za novac i zadovoljstva i zapiši ih. Unesi raznovrsnost u rutinu umesto da je rušiš: novi put do posla, novi recept, nova knjiga. Kreći se svakog dana, jer telu kod 14 treba izlaz za energiju."] },
    { title: "Četrnaest u ljubavi", paras: ["Četrnaestici u ljubavi treba partner koji razume potrebu za prostorom. Veze funkcionišu kad ima poverenja i zajedničkih avantura. Lekcija je da ostaneš i kad prvo uzbuđenje prođe, jer dubina dolazi baš tada."] },
    { title: "Četrnaest, posao i novac", paras: ["Najbolje se snalaze u poslovima sa dosta raznovrsnosti: putovanja, mediji, prodaja, turizam, događaji. Kod novca je ključ plan. Trajni nalog za štednju na početku meseca i poseban budžet za provod daju im slobodu bez ružnih iznenađenja."] },
    { title: "Pitanja za samoproveru", paras: ["Gde preterujem da ne bih nešto osetio? Koja granica bi mi donela više mira? Šta mi stvarno daje slobodu, a šta me samo uznemirava? Koja avantura vredi da je isplaniram umesto da je improvizujem?"] },
    { title: "Gde stoji 14 u karti", paras: ["Rođendan 14 daje živ, radoznao temperament kome trebaju nežne granice. Ako je reč o životnom putu, sloboda i umerenost postaju glavna lekcija celog života. U broju izraza obično se prepozna po karijeri sa dosta raznovrsnosti i rizika, gde je dobro rasuđivanje ključna veština. A kad stoji u broju duše, srce žudi za avanturom, ali se najviše smiri kad zna da ima sigurno mesto u koje se vraća."] },
    { title: "Četrnaest u porodici", paras: ["Porodicama u kojima je neko sa 14 koriste jasni, prijateljski dogovori: vreme za spavanje za dete sa 14, budžet za roditelja sa 14, plan za vikend koji obuhvata i zabavu i odmor. Pravila manje liče na kavez kad svi učestvuju u njihovom pisanju. Mnoge četrnaestice postanu izvor energije i smeha u porodici kad im je sloboda u ravnoteži."] },
    { title: "Kako da objasniš 14 prijatelju", paras: ["Možeš da kažeš: moj broj se tiče slobode, a naučio sam da najviše uživam kad sam sebi postavim nekoliko granica. Kad preteram, život me brzo vrati na zemlju. Sad planiram avanture i osećam se bolje, jer ih posle ne plaćam."] },
    { title: "Planirano uživanje", paras: ["Izaberi jedno zadovoljstvo nedeljno i uživaj u njemu potpuno i svesno, bez griže savesti i bez preterivanja. Obrok, izlet, veče napolju. Planirano uživanje uči um da umerenost vidi kao način da se život okusi, a ne kao zabranu."] },
    { title: "Pitanje za večeras", paras: ["Pitaj se: koje zadovoljstvo mi daje energiju, a koje mi je tiho uzima? Zapiši oba. Prvo zadrži, a drugom daj jasnu granicu na nedelju dana. Prati kako reaguju telo, novac i raspoloženje. Mali iskreni ogledi poput ovog nauče četrnaesticu više od bilo kog pravila."] },
    { title: "Četrnaest uz druge brojeve", paras: ["Svaki drugi broj u karti daje lekciji 14 drugačiju boju. Uz životni put 4 stabilnost pomaže nemirnom duhu da nađe ritam, a sloboda čuva četvorku od krutosti. Uz 2 potreba za bliskošću smiruje bežanje, ali traži iskren razgovor o prostoru. Uz 6 briga o porodici postaje sidro koje svakoj avanturi daje smisao. Uz 8 ambicija i želja za novim mogu da stvore veliki uspeh, ako se s novcem pažljivo postupa. Ma koja da je kombinacija, pitanje je jedno: koja mi granica daje više slobode umesto manje? Postavljeno jednom mesečno, to pitanje polako menja ceo obrazac."] },
    { title: "Telo i odmor", paras: ["Kod 14 telo često brzo reaguje na preterivanje: nesanica, glad za šećerom, nagli padovi energije. Redovan san, voda, kretanje na svežem vazduhu i obroci u isto vreme deluju kao tihi oslonac. Kad je telo smireno, i um lakše bira meru umesto viška, a avanture postaju radosnije."] },
    { title: "Poslednja misao", paras: ["Četrnaest uči da su sloboda i stabilnost partneri, ne suparnici. Putnik koji zna gde mu je dom može da ode dalje, da uživa više i da se vrati bez kajanja. Svaki put kad izabereš ravnotežu umesto viška, vraćaš sebi deo energije koju je stari obrazac trošio na oporavak."] },
  ],
  "karmic-debt/16": [
    { title: "Dug gordosti", paras: ["Šesnaest je karmički broj gordosti, ega i pada lažnih kula. Stari numerolozi u njemu vide dušu koja je nekad, u prošlom životu, zloupotrebila ljubav ili moć, često kroz sujetu ili neverstvo. U ovom životu ono što je podignuto na slici o sebi, a ne na istini, ima običaj da se uruši, ponekad preko noći. U tarotu je šesnaesta karta upravo Kula.", "Šesnaest se svodi na sedam, broj mudrosti i unutrašnje potrage. U tome je smisao ovog duga: svaki pad otvara vrata ka dubljem poznavanju sebe. Kula u koju udara grom izgleda zastrašujuće, ali mnogi koji čitaju tarot u njoj vide oslobođenje, jer pada ono što nikad nije ni bilo čvrsto."] },
    { title: "Kad se slika i istina raziđu", paras: ["Ljudi sa 16 često imaju jaku intuiciju i osete lažno pre nego što ga vide. U isto vreme umeju mnogo da ulažu u to kako izgledaju pred drugima. Kad se spoljašnja slika i unutrašnja istina raziđu, život ih suoči s tim: veza se iznenada završi, posao se izgubi, plan se sruši.", "Ove krize bole, ali ne znače kraj. Mnoge šesnaestice kažu da su baš posle najvećeg pada našle svoj pravi put. Broj ume da donese i naviku da se ranjivost krije iza doteranog izgleda, pa lekcija traži ono najteže: da priznaš grešku, da zamoliš za oproštaj, da pokažeš kakav si stvarno."] },
    { title: "Tri priče o broju 16", paras: ["Rođena šesnaestog, Jelena je kao menadžerka godinama krila preopterećenost iza osmeha. Kad je u reorganizaciji izgubila mesto, prvi put je sebi dozvolila da se odmori. Godinu dana kasnije otvorila je malu konsultantsku firmu koju vodi po svojim pravilima i kaže da nikad nije bila mirnija.", "Muzičar Stefan je gradio karijeru na imidžu i žurkama. Kad se publika povukla, počeo je da piše iskrene pesme o svojim greškama. One su stigle do mnogo više ljudi nego sve što je pre toga uradio.", "Razvod je jednoj ženi čiji životni put ide preko 16 u prvi mah izgledao kao katastrofa. U godinama posle toga otkrila je meditaciju, vratila se studijama i danas pomaže drugim ljudima u teškim periodima."] },
    { title: "Darovi broja 16", paras: ["Kad prihvati lekciju, osoba sa 16 postaje duboka, mudra i intuitivna. Ovi ljudi imaju dara za psihologiju, duhovnost, istraživanje i pisanje. Druge razumeju u krizama jer su i sami kroz njih prošli, pa umeju da ostanu mirni pored njih. Njihova iskrenost je retka i vredna."] },
    { title: "Senke broja 16", paras: ["Najdužu senku na ovaj broj baca gordost: potreba da se uvek izgleda uspešno, nemogućnost da se prizna greška, hladna distanca prema drugima. Posle jednog pada javlja se i strah od sledećeg, zbog koga se izbegavaju bliskost i rizik. Izlaz je skromnost, a skromnost ovde znači iskrenost bez maske, nikako poniženje."] },
    { title: "Vežbe za 16", paras: ["Priznaj sitne greške na vreme, pre nego što postanu velike. Vodi dnevnik iskrenosti. Svakog dana odvoji malo vremena za tišinu. Kad se nešto ruši, pitaj se šta to lažno pada, a šta pravo ostaje. Potraži podršku umesto da se zatvoriš u sebe."] },
    { title: "Šesnaest u ljubavi", paras: ["U ljubavi 16 uči da bliskost traži ranjivost. Veze sagrađene na idealizovanju često puknu, a one sagrađene na iskrenosti rastu. Odanost i otvorenost su najbolja zaštita od starih obrazaca."] },
    { title: "Posao, novac i rezerva", paras: ["Šesnaestice blistaju u istraživanju, psihologiji, nauci, pisanju i duhovnim zanimanjima. Kod novca je lekcija da ne ulažeš sve u jedan imidž ili jedan projekat. Rezerva na računu i skromne navike donose mir kad stigne promena."] },
    { title: "Pitanja pred ogledalom", paras: ["Gde još uvek štitim imidž umesto da kažem istinu? Šta sam naučio iz poslednjeg velikog pada? Pred kim mogu da skinem masku? Šta bi izgradila osoba koja se ne plaši grešaka?"] },
    { title: "Gde stoji 16 u karti", paras: ["Ko je rođen šesnaestog, nosi jaku intuiciju i osetljivost na lažno, kod drugih i kod sebe. Životni put sa 16 za glavnu temu ima ponovno građenje posle padova i traženje unutrašnje istine. Broj izraza to ume da pokaže kao karijeru koja naglo promeni pravac pre nego što se smiri u smislenom poslu. Broj duše govori o nekome ko u sebi traži duhovnu dubinu i pravu bliskost."] },
    { title: "Šesnaest u porodici", paras: ["U porodicama se 16 često javlja kod osobe koja pred svima održava privid da je sve u redu. Lekcija poziva na iskrenije razgovore: da se prizna kad je teško, da deca vide da odrasli greše i popravljaju greške. Porodice koje to uče zajedno često su posle krize bliže nego pre nje."] },
    { title: "Kad te neko pita za 16", paras: ["Reci mu otprilike ovako: moj broj govori o gordosti i skromnosti. Nekoliko puta u životu srušilo mi se ono što sam gradio na imidžu. Bolelo je, ali sam svaki put naučio da gradim na nečem istinitijem. Danas se trudim da govorim iskreno od početka, da život ne mora da me uči tako glasno."] },
    { title: "Pismo sebi", paras: ["Jednom mesečno napiši kratko pismo sebi o jednoj grešci i o tome šta te je naučila. Nikome ga ne šalji. Na kraju godine pročitaj sva pisma. Često pokažu koliko je mudrosti sakupilo tvoje iskustvo i kako je svaki pad otvorio neka vrata."] },
    { title: "Večeras se pitaj", paras: ["Gde još držim fasadu i ćutim o onome što je tačno? Izaberi jedno malo mesto i budi iskren tamo sutra, nežno i bez drame. Primeti koliko ti je lakše."] },
    { title: "Ko visoko leti", paras: ["Kod nas se kaže: ko visoko leti, nisko pada. Stari su znali da skromna kuća na čvrstim temeljima stoji duže od raskošne na pesku. Šesnaest ponavlja istu pouku: gradi na istini, a izgled neka dođe posle."] },
    { title: "Šesnaest uz druge brojeve", paras: ["Pored drugih brojeva lekcija 16 menja ton. Životni put 8 traži da se ambicija gradi na iskrenosti, jer je bez nje uspeh krhak. Uz 3 šarm i dar za reči treba da služe istini, umesto maski. Uz 9 saosećanje prema drugima pomaže da se gordost pretvori u mudrost. Uz 1 jaka volja uči da je priznata greška nov početak pre nego poraz. Šta god da stoji pored šesnaestice, pitanje se vraća: šta je u mom životu pravo i gradim li baš na tome? Kad je odgovor iskren, sledeći pad često bude manji ili izostane."] },
    { title: "Gde se stres krije u telu", paras: ["Kod 16 se stres često smesti u telo pre nego što se prizna rečima: stegnuta ramena, plitak dah, glavobolja. Šetnja u tišini, dug izdah i razgovor sa osobom od poverenja mogu da pomognu da napetost izađe pre nego što postane kriza."] },
    { title: "Šta ostaje", paras: ["Šesnaest traži tihu hrabrost: hrabrost da te vide onakvog kakav jesi. Svaka iskrena reč, svaka priznata greška i svaki trenutak skromnosti čine sledeći pad manjim, jer je ostalo manje lažne konstrukcije koja može da se sruši. Ono što preostane je jezgro koje nijedna bura ne može lako da potrese."] },
  ],
  "karmic-debt/19": [
    { title: "Dug moći", paras: ["Devetnaest nosi karmičku temu moći, nezavisnosti i samostalnosti. Smatra se da pripada duši koja se u ranijem životu sebično služila moći, nije marila za potrebe drugih ili je živela kao da joj sve pripada. U ovom životu lekcija ide obrnuto: da naučiš da stojiš na svojim nogama, ali i da prihvatiš pomoć, da vodiš, ali i da slušaš.", "Devetnaest se svodi na jedan, broj početka i vođstva. Ključ je vođstvo koje služi ljudima, umesto da vlada njima. Prava vodeća uloga, uči ovaj broj, ostavlja mesta i za druge."] },
    { title: "Sve sam, i kad ne mora", paras: ["Ljudi sa 19 često se osećaju usamljeno čak i među ljudima. Sve rade sami, teško traže pomoć i veruju da svaki problem moraju da reše bez ičije podrške. Život ih stavlja u situacije u kojima moraju da se snađu sami, ili u kojima moraju da nauče da prihvate ruku: bolest koja traži negu, projekat prevelik za jednog čoveka. Ponekad se javi tvrdoglavost i nestrpljenje prema tuđem mišljenju.", "Tajna broja 19 je u tome što se snaga i međuzavisnost ne isključuju. Najjače vođe znaju kad da pruže ruku i zatraže pomoć."] },
    { title: "Tri priče o broju 19", paras: ["Vesna, preduzetnica rođena devetnaestog, godinama je sama vodila sve u svojoj firmi i bila na ivici iscrpljenosti. Kad je našla prvog partnera kome veruje, firma se za dve godine udvostručila, a ona je ponovo počela da ide na godišnji odmor.", "Jedan lekar je uvek odlučivao sam i retko se konsultovao. Posle jedne teške greške počeo je redovno da razgovara sa kolegama. Njegovi pacijenti danas kažu da ih niko u bolnici ne sasluša kao on.", "Baba Ruža iz Kragujevca, čiji životni put ide preko 19, decenijama nikome nije dala da joj pomogne. Kad je posle operacije morala da prihvati pomoć unuka, otkrili su novu bliskost, a ona je rekla da joj je to bila najlepša godina u životu."] },
    { title: "Darovi broja 19", paras: ["Tvrdoglavost broja 19, kad se smiri, postaje pravo vođstvo: hrabrost, inicijativa, originalnost i sposobnost da se nešto pokrene od nule. Ovi ljudi su odlični osnivači, vođe, pioniri. Kad nauče da dele moć, njihova snaga podigne sve oko njih."] },
    { title: "Senke broja 19", paras: ["Kod 19 sebičnost retko izgleda kao sebičnost. Krije se u potrebi za kontrolom, u nepoverenju prema drugima, u gordosti koja ne dozvoljava pomoć. Tu je i usamljenost, iza zidova koje je čovek sam podigao. Rešenje je postepeno, svesno otvaranje prema drugima."] },
    { title: "Vežbe za 19", paras: ["Svake nedelje zatraži pomoć za jednu malu stvar. Pred odluku koja se tiče i drugih pitaj ih za mišljenje. Vežbaj da saslušaš do kraja, bez prekidanja. Priznaj kad neko drugi ima bolju ideju i reci mu to."] },
    { title: "Devetnaest u ljubavi", paras: ["Devetnaestica u ljubavi uči ravnopravnost: partner je saigrač, nikako projekat ili publika. Veze cvetaju kad se odluke donose zajedno i kad 19 smogne hrabrosti da pokaže ranjivost pored snage."] },
    { title: "Posao, novac i tim", paras: ["Devetnaestice su prirodni preduzetnici, menadžeri i samostalni profesionalci. Na poslu je lekcija delegiranje i timski rad. Kod novca je lekcija i davanje: velikodušnost i ulaganje u druge ljude često se vrate na neočekivane načine, mada ne obavezno kao novac."] },
    { title: "Pitanja o kontroli", paras: ["Šta nosim sam, a neko drugi bi to rado podelio sa mnom? Kad sam poslednji put zatražio pomoć i kakav je bio osećaj? Gde moja potreba za kontrolom oduzima prostor drugima? Ko stoji iza mene, a još nije dobio moju zahvalnost?"] },
    { title: "Gde stoji 19 u karti", paras: ["Rođendan 19 daje jaku volju i dar za inicijativu, a lekcija je da naučiš da deliš kontrolu. Na životnom putu sve se vrti oko nezavisnosti i saradnje. U broju izraza najčešće ga vidiš kod ljudi na vodećim mestima, koji uspevaju tek kad počnu da veruju drugima. U broju duše ostavlja trag dve želje: da stojiš na svojim nogama i, tiše, da te neko zagrli."] },
    { title: "Devetnaest u porodici", paras: ["Kod kuće je 19 često onaj koji sve preuzima na sebe, od slave i praznika do kriza. Lekcija traži da se podele zadaci i odluke. Deci devetnaestica koristi kad dobiju pravu odgovornost, a partneri se osećaju cenjeno kad njihovo mišljenje oblikuje plan. Porodica koja deli moć mirnija je i jača."] },
    { title: "Kako da objasniš 19 nekom bliskom", paras: ["Recimo ovako: moj broj je broj nezavisnosti. Ranije sam mislio da je traženje pomoći slabost. Život me je stalno stavljao u situacije u kojima nisam mogao bez drugih. Sad tražim ranije i otkrio sam da ljudi u stvari vole da pomognu, a i meni to prija."] },
    { title: "Spisak zahvalnosti", paras: ["Svake nedelje zapiši ime jedne osobe koja ti je pomogla i pošalji joj kratku zahvalnost, makar porukom na Viberu. Vremenom spisak pokaže koliko ljudi stoji iza tebe i nežno rastvara uverenje da si sam na svetu."] },
    { title: "Jedno pitanje pred spavanje", paras: ["Koji teret vučem sam, a neko bi mi ga rado olakšao? Imenuj osobu i zadatak. Sutra je zamoli, jednostavno i direktno. Zatim primeti kakav je osećaj kad primiš pomoć a ništa od sebe ne izgubiš. Većina devetnaestica otkrije da je to olakšanje, daleko od slabosti."] },
    { title: "Devetnaest na poslu, u jednom primeru", paras: ["Jedna šefica tima sa 19 prestala je da sama prepravlja sve izveštaje i počela je da nacrte pregleda zajedno sa kolegama. Rokovi su se češće poštovali, večeri su joj se vratile, a dvoje mlađih kolega je za godinu dana izraslo u jake analitičare."] },
    { title: "Devetnaest uz druge brojeve", paras: ["Lekcija 19 se menja u zavisnosti od toga šta joj stoji u susedstvu. Sa životnim putem 2 prirodna sklonost saradnji pomaže da se moć podeli bez straha. Sa 8 vođstvo i ambicija traže posebnu pažnju prema ljudima u timu. Sa 6 briga o drugima omekšava potrebu za kontrolom. Sa 5 želja za nezavisnošću mora da ostavi mesta i za bliske odnose. Šta god da stoji pored, devetnaestica se na kraju pita: koga mogu danas da uključim?"] },
    { title: "Teret u leđima", paras: ["Kod 19 se teret koji nosiš sam često oseti u leđima i vratu. Masaža, istezanje, sport u grupi i večeri bez obaveza uče telo da sme da se opusti. Odmor spada u snagu, i ne moraš da ga zaslužiš uspehom."] },
    { title: "Završna reč", paras: ["Devetnaest pokazuje da prava snaga obuhvata i sposobnost da se osloniš na nekog. Vođa koji ume da kaže „potreban si mi” stiče više odanosti od onoga koji nikad ne pokaže pukotinu. Svaki čin podeljenog poverenja olakšava stari teret i gradi krug oko tebe koji će te držati kad bude teško."] },
  ],
  "personal-year/1": [
    { title: "Primer: 4. maj", paras: ["Uzmimo nekog ko je rođen 4. maja. Za 2026. godinu mesec daje 5, dan daje 4, a sama godina daje 10, odnosno 1. Pet plus četiri plus jedan je deset, a deset se svodi na 1. Toj osobi je, dakle, 2026. lična godina 1, početak novog devetogodišnjeg ciklusa, dok će 2027. biti lična godina 2."] },
    { title: "Godina kroz godišnja doba", paras: ["Prvi meseci godine 1 često su nemirni. Stari ciklus je zatvoren, novi još nema oblik, pa se osećaš kao između dva stana: stari je predat, a ključeve novog još nemaš. Zato je ovo vreme da napraviš mesta i oslušneš šta u tebi hoće da počne. Pred kraj proleća misli se bistre i pojavljuju se prvi opipljivi koraci: prijava, razgovor, prva verzija nečega.", "Leto donosi zamah. Ono što je do juče bilo maglovit plan dobija obrise, pa i drugi počinju da primećuju da se nešto kuva. U jesen dolazi vreme za opredeljivanje: izaberi jedan ili dva pravca koji zaslužuju tvoju snagu, a ostalo pusti. Poslednji meseci su dobri za temelje koji će ti trebati u godini 2, a to su rutine, partnerstva i jednostavni sistemi."] },
    { title: "Ljubav u godini 1", paras: ["Ko je bez partnera, često upozna nekog novog, ili ponovo upozna sebe, i tada već jasnije zna šta hoće. Parovima ponekad treba novi vetar: zajednički projekat, selidba, drugačija podela uloga. Opasnost leži u nestrpljenju i u tome da gledaš samo u sebe. Godina 1 traži da budeš svoj do kraja, a da pri tom ostaviš mesta i za drugog."] },
    { title: "Posao i novac", paras: ["Numerolozi ovo čitaju kao dobru godinu da otvoriš svoju firmu, promeniš posao, potražiš unapređenje ili naučiš novu veštinu. U početku rezultati mogu biti mali, ali sada je važniji pravac nego iznos na računu. Kad je novac u pitanju, ulaži u alat, obrazovanje i sve što služi novom pravcu, a veliki rizik na koji te gura samo uzbuđenje ostavi za drugi put."] },
    { title: "Zdravlje i energija", paras: ["Energije uglavnom ima, ali ne ravnomerno: jedan dan bi pomerao planine, drugi dan ti se ne ustaje iz kreveta. Navika vežbanja koju započneš sada često potraje ceo ciklus. Pazi da te ne iscrpi to što sve nosiš na svojim leđima, i spavaj koliko ti treba, jer odluke ove godine zaslužuju odmornu glavu."] },
    { title: "Tri priče", paras: ["Medicinska sestra rođena 4. maja iskoristila je godinu 1 da se upiše na večernje časove fizioterapije. Prvi meseci su bili teški, posle smene jedva je stizala na predavanja, ali je do kraja ciklusa imala svoju ordinaciju.", "Čovek koji je petnaest godina radio u istoj firmi otvorio je u godini 1 malu onlajn prodavnicu, pored redovnog posla. Dve godine kasnije ta prodavnica mu je bila glavni prihod.", "Udovica u šezdesetim krenula je u godini 1 na časove slikanja, prosto zato što je to oduvek želela. Danas u svom gradu vodi grupu početnika."] },
    { title: "Šta da izbegneš", paras: ["Ne čekaj savršene uslove, jer oni u godini 1 retko dolaze. Ne hvataj se deset stvari odjednom. I ne vraćaj se onome što je godina 9 već zatvorila, starom poslu, staroj vezi, staroj navici, samo zato što ti je poznato."] },
    { title: "Šta da radiš tokom godine", paras: ["Napiši jednu rečenicu koja kaže šta nameravaš u ovom ciklusu i zalepi je na mesto koje svakog dana vidiš, recimo na frižider. Jednom mesečno napravi konkretan korak ka njoj. Vodi spisak početaka, ma koliko sitni bili. Kad se godina završi, pročitaj ga i primeti koliko je toga krenulo."] },
    { title: "Pitanja koja nosiš sa sobom", paras: ["O čemu želim da bude narednih devet godina? Šta imam želju da počnem, čak i ako se ne osećam spremno? Gde čekam dozvolu koju mogu da dam sebi?"] },
    { title: "Godina 1 u ciklusu", paras: ["Devetogodišnji ciklus teče kao priča. Godina 1 je prvo poglavlje, ono u kom glavni junak izlazi iz kuće i kreće. Ono što sada pokreneš raste kroz saradnju godine 2, izražavanje godine 3 i rad godine 4, sve do vrhunca oko godine 8 i zatvaranja u godini 9. Zato izbori iz godine 1 imaju toliku težinu: oni zadaju temu za skoro celu deceniju."] },
    { title: "Porodica i dom", paras: ["U kući godina 1 može da donese selidbu, novog člana porodice ili drugačiju podelu uloga. Deca možda kreću u novu školu ili odjednom pokažu koliko su samostalna. Pomaže da otvoreno popričate šta ko želi da započne, kako sveža snaga godine ne bi vukla porodicu na različite strane."] },
    { title: "Mali ritual za godinu", paras: ["Na rođendan ili prvog dana godine zapali sveću i napiši svoju nameru na karticu. Drži je u novčaniku ili u fioci. Kad se u mesecima koji slede osetiš izgubljeno, pročitaj je ponovo i upitaj se da li te današnji izbori vode bliže tome."] },
    { title: "Unutrašnja strana godine", paras: ["Iznutra, godina 1 traži poverenje u sebe. Meditacija, jutarnje beleške ili tihe šetnje pomažu ti da čuješ sopstveni glas pre nego što ga nadglasaju tuđa mišljenja. Ako je oko tebe mnogo saveta, pet minuta sa sobom pre prve kafe sasvim je dobar početak. Hrabrost koju sada gradiš trebaće ti tokom celog ciklusa."] },
    { title: "Polaženik i prvi korak", paras: ["U mnogim srpskim kućama prvi gost na Božić, 7. januara, zove se polaženik. Ulazi desnom nogom, čestita praznik i domaćinima želi zdravlje i berićet, a veruje se da sa njim u kuću ulazi sreća za celu godinu. Godina 1 nosi istu želju: da prvi korak bude svestan, a da ono što posadiš pusti dobar koren."] },
    { title: "Godina 1 i tvoj životni put", paras: ["Ista godina 1 ne oseća se isto na svakom životnom putu. Za životni put 1 to je dvostruka snaga početka i može biti vrlo jaka. Za put 2 ili 6 traži hrabrost da nešto uradiš i za sebe, a ne samo za druge. Za put 7 početak je često unutrašnji: novi pravac razmišljanja, pre nego što se išta spolja promeni."] },
    { title: "Kratko na kraju", paras: ["Lična godina 1 je vreme setve, a žetva stiže mnogo kasnije. Sadi pažljivo, zalivaj često i imaj poverenja da će oblik onoga što sada počinješ postati jasan u godinama koje dolaze."] },
  ],
  "personal-year/2": [
    { title: "Primer: 9. januar", paras: ["Neka je datum rođenja 9. januar. U 2026. mesec daje 1, dan 9, a godina 1. Jedan plus devet plus jedan je jedanaest, što se svodi na 2, pa je 2026. ovoj osobi lična godina 2. Neki numerolozi je čitaju i kao godinu 11/2, sa pojačanom intuicijom i osetljivošću."] },
    { title: "Godina 2 od zime do zime", paras: ["Godina 2 počinje tiho. Posle zamaha godine 1 sve kao da je usporilo, i to ume da nervira. Prvi meseci služe za slušanje, skupljanje informacija i građenje odnosa. Planovi u međuvremenu rastu pod zemljom, gde ih niko ne vidi, pa ni ti.", "Proleće i leto često donose susrete i saradnje: to može biti kolega, mentor, partner ili prijatelj. Jesen ume da ti proveri strpljenje, kad se odluke odlažu zbog drugih ljudi, a ti danima čekaš odgovor na mejl. Poslednji meseci nagrađuju diplomatiju i stalnu brigu i spremaju te za stvaralačku godinu 3."] },
    { title: "Ljubav u godini 2", paras: ["Za odnose je ovo jedna od najvažnijih godina u ciklusu. Ako nemaš partnera, lakše ćeš nekog upoznati preko prijatelja ili na poslu nego ciljanom potragom. Parovi često postaju bliskiji ili se suočavaju sa onim što treba da zaceli. Osetljivost je velika, pa iskrena i nežna reč sada znači više nego inače."] },
    { title: "Saradnja, posao i novac", paras: ["Na poslu je ključ saradnja. Dobra je godina da uđeš u tim, nađeš poslovnog partnera ili staneš iza tuđeg projekta. Veliki samostalni počeci neka sačekaju. S novcem je slično: male redovne uštede i pažljivo pročitani ugovori bolji su od smelih poteza."] },
    { title: "Telo i osetljivost", paras: ["Energije može biti manje nego u godini 1. Osećanja jače deluju na telo, pa prijaju odmor, mirne rutine i vreme pored vode ili u prirodi, makar to bila šetnja kejom posle posla. Pazi na granice: tuđa raspoloženja se lako upiju, a to je česta zamka godine 2."] },
    { title: "Tri priče o strpljenju", paras: ["Dizajnerka rođena 9. januara udružila se u godini 2 sa programerom koga je upoznala na radionici. Njihov mali studio danas zapošljava šest ljudi.", "Otac jednog tinejdžera proveo je godinu 2 obnavljajući odnos sa sinom, kroz nedeljne šetnje bez telefona. Kaže da je to godina u kojoj je naučio da sluša.", "Vlasnica prodavnice čekala je u godini 2 osam meseci da se završe pregovori o zakupu. Strpljenje se isplatilo: dobila je desetogodišnji ugovor po poštenoj ceni."] },
    { title: "Čega da se čuvaš", paras: ["Ne teraj stvari na silu, godina 2 ide svojim tempom. Ne ugađaj svima dok ne padneš s nogu. Ne skrivaj svoje potrebe da bi sačuvao mir, jer neizgovorena ogorčenost u ovoj osetljivoj godini brzo raste."] },
    { title: "Male vežbe za godinu 2", paras: ["Vodi malu svesku osećanja i snova, jer je intuicija sada jaka. Vežbaj da ljubazno kažeš ne. Svakog meseca izaberi jedan odnos i posveti mu pravu pažnju: pismo, telefonski poziv, zajednički obrok."] },
    { title: "Pitanja za godinu 2", paras: ["Ko su moji pravi partneri u životu i na poslu? Gde mi treba više strpljenja, a gde čvršće granice? Šta tiho raste i ne sme prerano da se iskopava?"] },
    { title: "Godina 2 u ciklusu", paras: ["U priči od devet poglavlja godina 2 je trenutak kad junak sreće saveznike. Seme iz godine 1 sada pušta koren, daleko od tuđih očiju. Može ti izgledati da se ništa ne dešava, ali odnosi, dogovori i strpljenje ove godine odlučuju koliko će kasniji rast biti snažan. Mnogi se svoje godine 2 sećaju kao vremena kad su im u život ušli najvažniji ljudi."] },
    { title: "Dom i nežnost", paras: ["Život kod kuće u godini 2 traži nežnost. Sitnice vrede više od velikih gestova: zajednički doručak, poruka ostavljena na stolu, pomoć koju niko nije morao da traži. Ako u porodici postoje stare napetosti, ovo je dobra godina za posredovanje i strpljiv razgovor, dok sukob može da sačeka ili da se nikad ne desi."] },
    { title: "Ritual u paru", paras: ["Izaberi par predmeta, dva kamena, dve šolje, dve sveće, i stavi ih jedan pored drugog tamo gde ih svakog dana vidiš. Neka te podsećaju da je ovo godina partnerstva. Jednom nedeljno pomisli na nekog s kim ti je drago što radiš ili živiš, i reci mu to."] },
    { title: "Pitanje za večeras", paras: ["Pitaj se: čija mi je podrška do sada promakla, a kome mogu da pružim malo više svoje? Zapiši po jedno ime. Sutra uradi po jednu malu stvar za oboje. Godina 2 ovakve tihe razmene nagrađuje više od svakog velikog plana."] },
    { title: "Šta se dešava iznutra", paras: ["Iznutra, godina 2 izoštrava intuiciju. Snovi su živopisni, slučajnosti češće, osećanja jača. Mnogi ovo doživljavaju kao prirodno vreme za meditaciju, molitvu ili blagu vežbu disanja. Cilj je da budeš stabilniji u svetu, a ne da od njega pobegneš, kako bi ti osetljivost bila dar umesto tereta. Primeti koja mesta, ljudi i navike te smiruju i vraćaj im se često. Već nekoliko minuta tišine ujutru ume da promeni tok celog dana."] },
    { title: "Trenutak preokreta", paras: ["Mnogi primete preokret oko sredine godine 2, kad tih razgovor ili slučajan susret odjednom otvori vrata. U tom času to retko izgleda važno. Obrati pažnju na ljude koji se pojave nenametljivo i ostanu, jer oni često oblikuju ostatak ciklusa."] },
    { title: "Godina 2 i tvoj životni put", paras: ["Kako ćeš doživeti godinu 2 zavisi i od tvog životnog puta. Za put 1 ili 8 ona može biti vežba strpljenja, jer traži saradnju umesto vođenja. Za put 2 ili 6 prirodna je i prijatna, ali traži granice da se ne izgubiš u drugima. Za put 5 tih tempo može delovati dosadno, a upravo se tu uči ostajanje. Za put 7 nudi retku priliku za pravu bliskost sa nekoliko ljudi."] },
    { title: "Lepa reč", paras: ["Kod nas se kaže da lepa reč i gvozdena vrata otvara. Godina 2 potvrđuje tu staru mudrost: ljubazna reč, kafa s komšinicom i strpljivo slušanje otvaraju više vrata nego sila. Kad sledeći put nešto zapne, na šalteru, kod šefa ili kod kuće, probaj prvo tako."] },
    { title: "Za kraj", paras: ["Lična godina 2 je doba korena. Ono što sada tiho neguješ držaće te stabilno kad rast ponovo ubrza."] },
  ],
  "personal-year/3": [
    { title: "Primer: 14. jun", paras: ["Recimo da je neko rođen 14. juna. Za 2026. mesec daje 6, dan 14 daje 5, a godina daje 1. Šest plus pet plus jedan je dvanaest, a to se svodi na 3. Ovoj osobi je zato 2026. lična godina 3, a 2027. će biti godina 4."] },
    { title: "Kako se godina 3 odvija", paras: ["Godina 3 obično počinje boljim raspoloženjem. Posle strpljenja godine 2 život je lakši, a društvo bliže. U prvim mesecima dobro je probati nešto stvaralačko i upoznavati nove ljude.", "Proleće i leto često donose pozive, izlete i vidljivost. Ideje stižu same, pa je rizik da se rasparčaš. Jesen traži da izabereš koji kreativni projekti zaslužuju da budu završeni. Kraj godine je dobar da pokažeš šta si napravio i da u tome uživaš, pre nego što stigne ozbiljnija godina 4."] },
    { title: "Ljubav u godini 3", paras: ["Romantika je često razigrana. Ako si slobodan, više je prilika da nekog upoznaš u društvu, a flert dolazi sam od sebe. Parovima prijaju zabava, izleti i smeh. Izazov je dubina: lagani razgovori su lepi, ali i prava osećanja moraju jednom da budu izgovorena."] },
    { title: "Posao, nastupi i novac", paras: ["Povoljan je rad koji je stvaralački, komunikativan i pred ljudima: pisanje, dizajn, nastava, marketing, nastupi. Dobra je godina da pokažeš šta radiš, pokreneš blog ili govoriš na događajima. Para ume da dođe lako i da ode još lakše, pa uživaj, ali vodi jednostavan budžet, makar u svesci."] },
    { title: "Energija i raspoloženje", paras: ["Energija je obično vedra, ali kasne noći i društveni pritisak umeju da iscrpe. Izražavaj osećanja umesto da ih držiš u sebi, jer godina 3 oslobađa ono što je dugo bilo potisnuto. Pevanje, igranje i smeh sada znače više nego što bi rekao."] },
    { title: "Tri priče o izlasku pred ljude", paras: ["Nastavnica rođena 14. juna pokrenula je u godini 3 mali podkast o lokalnoj istoriji. Od toga je nastala nedeljna radio emisija.", "Računovođa koji je oduvek crtao u tajnosti izložio je skice u jednom kafiću. Tri rada su se prodala, a sada crta svakog vikenda.", "Jedan bračni par u penziji učlanio se u hor u godini 3 i za dvanaest meseci stekao više prijatelja nego za prethodnih deset godina."] },
    { title: "Zamke godine 3", paras: ["Ne rasipaj se na previše projekata. Kloni se ogovaranja i nepromišljenih reči, jer u godini 3 brzo putuju, naročito kroz Viber grupe. Ne krij tugu iza stalne veselosti."] },
    { title: "Navike za ovu godinu", paras: ["Napravi nešto svake nedelje, koliko god da je malo. Vodi spisak ideja i za svako godišnje doba izaberi po jednu koju ćeš završiti. Bar jednom mesečno prihvati poziv od kog te malo hvata trema."] },
    { title: "Pitanja za godinu 3", paras: ["Šta želim da izrazim ove godine? Koja od mojih mnogih ideja zaslužuje da bude završena? Gde se krijem iza osmeha?"] },
    { title: "Godina 3 u ciklusu", paras: ["Ako ciklus čitaš kao roman, godina 3 je mesto gde junak pronalazi svoj glas. Ideja iz godine 1 i saveznici iz godine 2 sada izlaze pred svet. To je vreme deljenja, pokazivanja i slavlja. Ono što sada izraziš privlači ljude i prilike koje će uporan rad u godini 4 pretvoriti u nešto trajno."] },
    { title: "Živa kuća", paras: ["Godina 3 unosi više života u kuću: gosti, proslave, muzika, kreativni projekti sa decom. Divna je to godina za porodične običaje i okupljanja koja ponovo povezuju rodbinu. Samo pripazi na reči kad se zakuva, jer nepromišljena primedba sada odzvanja duže nego inače."] },
    { title: "Sveska radosti", paras: ["Vodi svesku radosti. Svake večeri zapiši jednu stvar koja te je nasmejala, razveselila ili inspirisala. Na kraju meseca pročitaj stranice. Ta navika uči glavu da primećuje radost, a radost je pravo gorivo godine 3, dok sveska s vremenom postaje zaliha ideja za kasnije."] },
    { title: "Pitanje pred spavanje", paras: ["Upitaj se: šta bih stvarao kad niko ne bi sudio? Izaberi jednu malu formu, skicu, pesmu, recept, melodiju, i napravi je ove nedelje. Pokaži je jednoj osobi kojoj veruješ. Godina 3 se otvara kad ono što napraviš neko i čuje."] },
    { title: "Prijateljstvo u godini 3", paras: ["Prijateljstva se u godini 3 često množe. Stari prijatelji se ponovo javljaju, a novi stižu preko hobija, kurseva i žurki. Uživaj u toj šarenoj gužvi i primeti koja te prijateljstva hrane, a koja samo pune kalendar. Ona koja te hrane vredi negovati i u tišim godinama koje dolaze."] },
    { title: "Radost kao praksa", paras: ["Iznutra, godina 3 traži da radost otkriješ kao duhovnu praksu. Zahvalnost, igra i lepota ove godine vode ka unutrašnjem rastu, umesto da te od njega odvlače. Primeti šta te najviše oživljava i daj tome mesto u svakoj nedelji. Stvaralački rad obavljen s punom pažnjom ume da liči na meditaciju. Ako se pojavi tuga, pusti i nju da izađe, kroz pisanje, muziku ili suze, jer se u ovoj godini osećanja ne spremaju u fioku."] },
    { title: "Ideja koja se izdvoji", paras: ["Preokret često dolazi u drugoj polovini godine 3, kad se jedna kreativna ideja odvoji od ostalih i počne da privlači pravo interesovanje. Prepoznati je i dati joj više vremena nego drugima glavna je veština ove godine i most ka godini 4."] },
    { title: "Pesma i kolo", paras: ["Retko koja svadba kod nas prođe bez pesme i kola. Godina 3 nosi isti duh: radost se deli, ne čuva se za sebe. Uhvati se u kolo, zapevaj na svadbi, pozovi prijatelje za sto. Tu se rađaju najlepše ideje."] },
    { title: "Godina 3 i tvoj životni put", paras: ["Životni put boji godinu 3 na svoj način. Za put 3 to je dvostruka radost i velika stvaralačka snaga. Za put 4 ili 8 traži dozvolu za igru i odmor, a ta dozvola ne dolazi uvek lako. Za put 7 izraz će pre ići kroz pisanje nego kroz javne nastupe. Za put 9 stvaranje često dobija humanitarni cilj."] },
    { title: "Poslednja reč", paras: ["Lična godina 3 je doba cveća. Dozvoli sebi da procvetaš, pokaži svoju boju i uživaj na svetlu, a usput izaberi nekoliko semenki za posao koji dolazi."] },
  ],
  "personal-year/4": [
    { title: "Primer: 23. jul", paras: ["Evo nekog ko je rođen 23. jula. U 2026. mesec daje 7, dan 23 daje 5, a godina daje 1. Sedam plus pet plus jedan je trinaest, što se svodi na 4. Za ovu osobu 2026. je, prema tome, lična godina 4, godina rada i temelja."] },
    { title: "Godina 4, doba po doba", paras: ["Godina 4 često počinje osećajem dužnosti. Posle lakoće godine 3 obaveze izbijaju u prvi plan: papiri i overe, popravke, lekarski pregledi, poslovi koji čekaju od prošle zime. Prvi meseci su za sređivanje i za plan koji može da se ispuni, a ne za spisak želja.", "Proleće i leto su vreme istrajnog rada. Napredak može da izgleda spor, ali svaki završen zadatak učvršćuje osnovu. Jesen disciplinu nagrađuje rezultatima koji se vide. Pred kraj godine pregledaj šta si izgradio i spremi se za promene i pokret godine 5."] },
    { title: "Ljubav u godini 4", paras: ["Ljubav postaje praktična. Parovi počinju da žive zajedno, kupuju stan, venčavaju se ili prosto uvode bolje rutine, pa se konačno zna ko vodi dete na trening, a ko plaća račune. Oni bez partnera često radije biraju stabilnu, sigurnu vezu nego uzbudljivu a nesigurnu. Rizik je da se romantika izgubi među obavezama, pa vreme za nežnost planiraj jednako pažljivo kao kućni budžet."] },
    { title: "Rad, veštine i novac", paras: ["Ovo je godina napornog rada, sticanja veština i pravljenja sistema. Dobra je za završavanje kvalifikacija, sređivanje posla, renoviranje ili dugoročnu štednju. Prečice sada retko uspevaju. Kad je o novcu reč, jasan budžet i vraćeni dugovi donose veliko olakšanje, a malo šta prija kao poslednja plaćena rata kredita."] },
    { title: "Telu treba red", paras: ["Telo traži strukturu: redovan san, dobru hranu, stalno kretanje. Odlična je godina za preglede i da se, uz lekara, konačno pozabaviš starim zdravstvenim tegobama. Glavni rizik je premor, pa odmor upiši u raspored kao i svaku drugu obavezu."] },
    { title: "Tri priče o upornosti", paras: ["Čovek rođen 23. jula iskoristio je godinu 4 da renovira kuću svojih dede i babe, sobu po sobu. Do decembra je porodica ponovo imala vikendicu.", "Studentkinja je u godini 4 rešila da uči dva sata dnevno i položila ispit na kom je pre toga dva puta pala.", "Vlasnica male pekare provela je godinu 4 zapisujući svaki recept i postupak. Sledeće godine je mogla da zaposli ljude i konačno ode na odmor."] },
    { title: "Šta ne pomaže", paras: ["Kloni se krutosti i uverenja da je odmor lenjost. Ne tovari na sebe tuđe odgovornosti samo zato što umeš da ih nosiš. Drži se dalje od velikih rizika: godina 4 nagrađuje strpljenje, a kocku ne."] },
    { title: "Nedeljni red", paras: ["Nedeljom uveče napravi jednostavan plan za narednih sedam dana. Svakog dana završi po jedan praktičan zadatak. Prati koliko trošiš i koliko spavaš. Završen posao proslavi nečim malim i prijatnim."] },
    { title: "Pitanja za godinu 4", paras: ["Kakav temelj želim da izgradim ove godine? Koji mi nezavršen posao crpi snagu? Gde mojoj disciplini treba više blagosti?"] },
    { title: "Godina 4 u ciklusu", paras: ["Četvrto poglavlje devetogodišnje priče je ono u kom junak zida kuću. Ideji, saveznicima i glasu iz prve tri godine sada treba struktura. Ova godina može da deluje kao najmanje uzbudljiva, a ipak često baš ona odlučuje da li će ciklus doneti nešto trajno. Rad uložen sada nosi te kroz promene godine 5 i odgovornosti godine 6."] },
    { title: "Kuća, papiri i stariji", paras: ["Dom mnogo znači u godini 4. Popravke, selidbe, renoviranja i sređivanje domaćinstva idu uz ovu godinu. Porodicama pomažu jasne rutine i podeljeni kućni poslovi. Dobro je i da se sada pobrineš za starije rođake i središ praktične stvari kao što su dokumenta, osiguranja i testamenti."] },
    { title: "Jedan sređen kutak", paras: ["Izaberi jedan kutak u kući i drži ga savršeno sređenim cele godine: radni sto, policu, fioku u kuhinji. Svaki put kad ga pogledaš, neka te podseti da se red gradi malim potezima. Mnogi primete da se mir iz tog kutka polako širi na ceo stan."] },
    { title: "Večerašnje pitanje", paras: ["Postavi sebi pitanje: koja bi mi jedna stvar, kad bih je završio, olakšala ostatak godine? Zapiši je i podeli na tri koraka. Prvi uradi već sutra. Godina 4 takve sitne korake pretvara u čvrste zidove."] },
    { title: "Prijateljstvo u godini 4", paras: ["Društveni život u godini 4 može da se utiša, i to je prirodno. Prijatelji koji ostanu često su najverniji, i s njima se grade odnosi za ceo život. Jednostavni, redovni susreti, nedeljna šetnja ili večera jednom mesečno, bolje pristaju ovoj godini nego velike žurke."] },
    { title: "Disciplina iznutra", paras: ["Iznutra, godina 4 uči da disciplina može biti oblik posvećenosti. Obični poslovi urađeni s pažnjom, oprani sudovi, održana obećanja, završeni izveštaji, postaju vežba prisutnosti. Stalni rituali kao što su dnevna šetnja, nedeljni dan odmora ili kratko večernje razmišljanje daju glavi okvir koji je drži kroz teške mesece. Mnogi otkriju da strpljenje stečeno sada prelazi u tihu unutrašnju snagu, koja ostaje i dugo pošto se godina završi."] },
    { title: "Kad se trud pokaže", paras: ["Preokret često dolazi pred kraj godine 4, kad se trud od mnogo meseci odjednom pokaže: završena kvalifikacija, renovirana soba, stabilan budžet. Odvoji trenutak da to jasno vidiš i da sebi zahvališ, jer to priznanje daje snagu za promene koje slede."] },
    { title: "Majstori iz Crne Trave", paras: ["Crna Trava je poznata po graditeljima koji su godinama radili daleko od kuće, kao pečalbari. Svako ko je ikad zidao zna ono što su znali i oni: temelj se ne požuruje. Godina 4 nosi istu mudrost, jer se temelj gradi poštovanjem, strpljenjem i zajedništvom. Ove godine si i ti pomalo majstor, red po red, dan za danom."] },
    { title: "Godina 4 i tvoj životni put", paras: ["Godina 4 ne steže sve jednako, mnogo zavisi od životnog puta. Za put 4 prirodna je, ali traži da ne preteruješ s radom. Za put 3 ili 5 može da deluje tesno, kao odelo koje steže, a opet baš struktura pomaže tim talentima da donesu plod. Za put 1 rad postaje osnova za sledeći veliki potez. Za put 9 gradnja je često namenjena drugima: porodici, zajednici, nekom cilju. Za put 6 dom postaje centar, a za put 2 zajednički rad sa partnerom donosi najviše mira i zadovoljstva."] },
    { title: "Na kraju", paras: ["Lična godina 4 je doba gradnje. Postavi svaki kamen s pažnjom, i zidovi koje sada dižeš čuvaće te kad godine koje dolaze sve pokrenu."] },
  ],
  "personal-year/5": [
    { title: "Primer: 5. avgust", paras: ["Računamo za rođendan 5. avgusta. U 2026. mesec daje 8, dan 5, a godina 1. Osam plus pet plus jedan je četrnaest, što se svodi na 5. Ovoj osobi je onda 2026. lična godina 5, sredina devetogodišnjeg ciklusa i njegov veliki preokret."] },
    { title: "Šta donosi koje doba", paras: ["Godina 5 često počinje osećajem da nešto mora da se promeni. Posle upornog rada godine 4 rutine koje su do juče davale sigurnost počinju da stežu. Prvi meseci donose vesti, nemir i neočekivane ponude, pa se možda zatekneš kako u autobusu gledaš oglase za stan u drugom gradu.", "Proleće i leto su živi: putovanja, selidbe, novi ljudi, nov posao. Neke promene biraš, druge se dese same. Jesen traži da prebereš mogućnosti i zadržiš ono što podržava tvoj pravac. Završni meseci neka posluže da se novi oblik života slegne, pre nego što stignu odgovornosti godine 6."] },
    { title: "Ljubav u godini 5", paras: ["Romantika može biti uzbudljiva i nepredvidiva. Ako si bez partnera, možda ćeš nekog upoznati na putu ili kad se tvoje društvo naglo promeni. Parovima često treba svež vazduh: zajednički odlazak negde, nov hobi, više slobode za svakog od dvoje. Iskrenost je važna, jer godina 5 izbacuje na videlo sve što je bilo previše stegnuto ili skriveno."] },
    { title: "Posao u pokretu i novac", paras: ["Promena je na poslu povoljna: nove uloge, nove oblasti, službeni put, samostalan rad, marketing i sve gde ima ljudi i kretanja. Dobra je godina da osvežiš veštine i prihvatiš ponude koje te malo rastežu. Zarada može da stigne naglo i isto tako nestane, pa čuvaj rezervu i pažljivo čitaj ugovore pre potpisa."] },
    { title: "Kretanje i mera", paras: ["Energija raste i pada zajedno sa uzbuđenjem. Kretanje mnogo pomaže: igranje, planinarenje, bicikl, plivanje. Pazi na preterivanje sa hranom, alkoholom, ekranima ili trošenjem, jer godina 5 iskušava čula. San i jednostavni obroci drže telo na zemlji dok život juri."] },
    { title: "Tri priče o promeni", paras: ["Menadžerka prodaje rođena 5. avgusta prihvatila je u godini 5 šestomesečni posao u inostranstvu. Vratila se sa novim jezikom, više samopouzdanja i boljom pozicijom.", "Mladi otac koji nikad nigde nije putovao poveo je porodicu na kampovanje širom Balkana. Sada svakog leta planiraju po jednu avanturu.", "Inženjer u penziji počeo je u godini 5 da dobrovoljno vodi turiste kroz svoj grad. Kaže da su ga razgovori sa posetiocima iz celog sveta podmladili za dvadeset godina."] },
    { title: "Gde se lako pogreši", paras: ["Ne menjaj sve odjednom samo da pobegneš od dosade. Ne donosi nagle odluke o novcu, vezama ili zdravlju. Ne beži ni od lekcija godine 4: temelje zadrži, a menjaj ono što stoji na njima."] },
    { title: "Male vežbe promene", paras: ["Svakog meseca probaj nešto novo: mesto, jelo, veštinu, drugu liniju do posla. Vodi dnevnik putovanja ili promena. Pred svaku veliku odluku prespavaj jednu noć. Pokreni telo svakog dana, makar deset minuta."] },
    { title: "Pitanja za godinu 5", paras: ["Šta je u mom životu spremno za promenu? Za kojom slobodom čeznem i koliko bi me koštala? Kako da dočekam novo, a da ne izgubim ono što mi je važno?"] },
    { title: "Godina 5 u ciklusu", paras: ["Na polovini devetogodišnje priče junak napušta sigurnu kuću da bi video svet. Ono što je izgrađeno u godini 4 sada se sudara sa pravim životom. Iskustva ove godine donose sveže ideje i poznanstva, a godina 6 će od njih napraviti obaveze, godina 7 mudrost. To je sredina ciklusa i mnogi je pamte kao godinu kad se sve pomerilo."] },
    { title: "Dom u pokretu", paras: ["U kući se u godini 5 mnogo toga pomera: selidbe, posete, zajednička putovanja, promene u tome ko gde živi. Tinejdžeri mogu da traže više samostalnosti. Fleksibilne rutine rade bolje od strogih, a porodične avanture, pa i mali jednodnevni izleti, drže sve na okupu dok život ubrzava."] },
    { title: "Mapa novih mesta", paras: ["Čuvaj mapu, papirnu ili u telefonu, i označi svako novo mesto koje ove godine posetiš, čak i nov kafić u sopstvenom gradu. Na kraju godine pogledaj oznake. Podsetiće te da promena ne mora samo da ti se dešava: možeš i da je izabereš i da u njoj uživaš."] },
    { title: "Pitanje za ovu nedelju", paras: ["Zapitaj se: koja bi mala promena ove nedelje unela svež vazduh u moj život? Izaberi je, isplaniraj i uradi. Godina 5 najbolje odgovara na radoznalost koja se pretvori u delo."] },
    { title: "Prijateljstvo u godini 5", paras: ["Novi prijatelji stižu lako, često iz drugih sredina i zemalja. Stari mogu da se presele ili promene, pa Viber poruka tu i tamo vredi više nego što misliš. Održavaj vezu sa onima koji ti znače i uživaj u boji koju novi ljudi unose."] },
    { title: "Sloboda u glavi", paras: ["Iznutra, godina 5 uči da sloboda počinje u glavi. Kad pustiš stara uverenja, probaš nove prakse i pogledaš svet tuđim očima, oslobađaš se koliko i na bilo kom putu u inostranstvo. Svesnost ti pomaže da uživaš u trenutku, a da ne juriš sledeće uzbuđenje."] },
    { title: "Događaj koji menja pravac", paras: ["Preokret često dolazi na sredini godine 5, kad jedan neočekivan događaj, poziv, ponuda, susret, promeni pravac narednih godina. Prepoznaj ga, shvati ga ozbiljno i daj mu prostora."] },
    { title: "Voda za putnikom", paras: ["Kod nas se za onim ko kreće na put prospe voda, da mu put teče kao voda. Godina 5 je godina puta, pa joj ta stara želja baš pristaje: da sve teče lako, da donese dobro i da te vrati kući bogatijeg za jedno iskustvo."] },
    { title: "Godina 5 i tvoj životni put", paras: ["Za životni put 5 ovo je duplo više promene i može biti vrlo dinamično. Za put 4 ili 6 promene mogu da izgledaju preteće, ali donose svežinu koja je dugo nedostajala. Za put 7 najviše se pomera u glavi: nove ideje i novi pogledi, dok spolja sve može da ostane isto."] },
    { title: "Jedna misao za kraj", paras: ["Lična godina 5 je doba vetra. Otvori prozore, pusti svež vazduh i putuj lako, ali drži koren dovoljno duboko da najbolje sa puta doneseš kući."] },
  ],
  "personal-year/6": [
    { title: "Primer: 2. mart", paras: ["Rođendan je 2. marta, pa krećemo od toga. U 2026. mesec daje 3, dan 2, a godina 1. Tri plus dva plus jedan je šest. Za ovu osobu je 2026. lična godina 6, godina doma, brige i odgovornosti."] },
    { title: "Od prvih poziva do kućnog mira", paras: ["Godina 6 često počinje porodičnim stvarima. Posle kretanja godine 5 ljudi i obaveze te zovu nazad: rođaku treba pomoć, kuća traži pažnju, veza traži odluku. Na početku godine važno je da čuješ te pozive i odrediš šta je prvo na redu.", "Od proleća do kraja leta nižu se obaveze: svadbe, selidbe, kućni ljubimci, deca, uloge u zajednici. Jesen može da proveri ravnotežu između brige za druge i brige za sebe. Poslednji meseci su dobri da napraviš sklad kod kuće i pripremiš se za tiho razmišljanje godine 7."] },
    { title: "Ljubav u godini 6", paras: ["Ovo je jedna od najjačih godina za ljubav i posvećenost. Parovi se često venčavaju, počinju zajednički život, dobijaju decu ili obnavljaju obećanja. Ko je sam, može da upozna nekog pored koga se oseća kao kod kuće. Stare rane u vezama izlaze na površinu da bi zacelile, a praštanje postaje glavna tema."] },
    { title: "Posao u službi drugih i novac", paras: ["Povoljan je rad u službi drugih: nastava, zdravstvo, savetovanje, dizajn, ugostiteljstvo i sve što ljudima daje osećaj da neko misli na njih. Odgovornosti na poslu mogu da porastu. Prirodno je da trošiš na kuću i porodicu, ali vodi budžet, da velikodušnost ne postane teret."] },
    { title: "Briga o sopstvenoj snazi", paras: ["Energija ide ka drugima, pa odmor mora da se planira. Zdravo kućno kuvanje, rad u bašti i vreme sa bliskim ljudima hrane telo. Pazi na stres od nošenja tuđih problema i zapamti da je briga o sebi deo brige o drugima."] },
    { title: "Tri priče o domu", paras: ["Žena rođena 2. marta dovela je u godini 6 ostarelu majku da živi kod nje. Bilo je teško, ali su postale bliskije nego što su bile decenijama.", "Mlad par je u godini 6 udomio psa, a godinu dana kasnije usvojio i dete. Zovu je godinom u kojoj je njihova kuća postala dom.", "Vlasnica kafića počela je jednom nedeljno da besplatno služi supu komšijama. Taj mali gest pretvorio je njen kafić u srce ulice."] },
    { title: "Gde da staneš", paras: ["Ne pokušavaj da popraviš svakoga. Kloni se perfekcionizma kod kuće i u vezama. Ne govori da na svaku molbu, sve dok za tebe ne ostane ništa."] },
    { title: "Male navike brige", paras: ["Svakog meseca ulepšaj kuću jednom sitnicom. Izdvoji jedno veče nedeljno za sebe. Vežbaj rečenicu: mogu da pomognem oko ovog dela, ali ne oko svega."] },
    { title: "Pitanja za godinu 6", paras: ["Za koga stvarno želim da brinem? Gde dajem previše? Šta bi moj dom učinilo mirnijim?"] },
    { title: "Godina 6 u ciklusu", paras: ["Šesto poglavlje vraća junaka kući, sa blagom nađenim usput, koje sada deli sa svojima. Sloboda godine 5 ovde se sreće sa odgovornošću. Ono čemu se sada posvetiš oblikuje dubinu godine 7 i uspeh godine 8."] },
    { title: "Porodica u centru", paras: ["Ove godine sve se vrti oko porodice. Okupljanja, proslave, slava i briga o deci i starijima pune kalendar. Dobra je godina da popraviš stare porodične veze, središ stan i započneš običaje koji će porodicu držati godinama."] },
    { title: "Jedan obrok nedeljno", paras: ["Izaberi jedan obrok nedeljno koji ćeš podeliti s ljudima koje voliš, za stolom, bez ekrana. Skuvajte nešto jednostavno, s pažnjom. Tokom godine ti obroci postaju puls vaših odnosa."] },
    { title: "Dva pitanja za večeras", paras: ["Pitaj se: ko je u poslednje vreme brinuo o meni i da li sam mu zahvalio? I o kome mogu sutra da se pobrinem na mali, stvaran način? Zapiši oba odgovora i uradi nešto po njima."] },
    { title: "Prijateljstvo u godini 6", paras: ["Prijateljstva postaju dublja i liče na porodicu. Možda će ti se ljudi češće obraćati za savet, pa telefon zazvoni i kad si već krenuo na spavanje. Pazi da briga teče u oba smera i dozvoli prijateljima da i oni tebe podrže."] },
    { title: "Nežnost prema sebi", paras: ["Iznutra, godina 6 je u znaku ljubavi u najširem smislu: prema drugima, prema lepoti i prema sebi. Zahvalnost i saosećanje sada dolaze prirodno. Najdublja lekcija je da zaslužuješ istu nežnost koju daješ."] },
    { title: "Naučiti da primaš", paras: ["Mnogi ljudi sa jakom godinom 6 kažu da su najviše naučili o primanju. Kad dopustiš drugima da ti skuvaju, pomognu pri selidbi ili saslušaju tvoje brige, i njima daješ radost brige. Godina je zaokružena kad ljubav teče u oba smera. Svake nedelje uhvati po jedan trenutak kad ti neko nudi pomoć i vežbaj da je prihvatiš jednostavno, sa „hvala” i bez izgovora. Ta mala navika često promeni ravnotežu u celoj porodici."] },
    { title: "Godina 6 i tvoj životni put", paras: ["Za životni put 6 ovo je briga u duploj meri i može da ispuni do kraja, ako granice izdrže. Za put 1 ili 5 može da deluje teško, jer se dužnost bori sa samostalnošću, a ipak često donosi najtoplije uspomene iz ciklusa. Za put 7 izazov je da otvori vrata i pusti ljude unutra. Za put 9 briga se lako širi sa porodice na celu zajednicu."] },
    { title: "Porodični preokret", paras: ["Preokret često dolazi kroz porodični događaj, rođenje, svadbu, bolest, susret posle dugo vremena, koji te podseti šta je najvažnije i odredi pravac narednih godina."] },
    { title: "Gost u kuću", paras: ["Gost u kuću, Bog u kuću, kaže se kod nas, a za stolom se završavaju svađe i počinju prijateljstva. Najbolje se to vidi na slavi, kad se kuća puni i vrata se ne zatvaraju do kasno. Godina 6 vraća taj običaj: otvori vrata, postavi sto, pozovi svoje."] },
    { title: "Slika za kraj", paras: ["Lična godina 6 je doba ognjišta. Pazi da vatra ne utrne, okupi svoje oko nje i ne zaboravi da i sam sedneš da se ogreješ."] },
  ],
  "personal-year/7": [
    { title: "Primer: 15. septembar", paras: ["Za primer nam treba jedan datum, neka bude 15. septembar. U 2026. mesec daje 9, dan 15 daje 6, a godina 1. Devet plus šest plus jedan je šesnaest, a to se svodi na 7. Ovoj osobi 2026. donosi ličnu godinu 7, godinu razmišljanja i unutrašnjeg rasta."] },
    { title: "Četiri doba jedne tihe godine", paras: ["Godina 7 često počinje željom da se povučeš. Posle užurbane brige godine 6 možda ti treba više vremena nasamo. Prvih meseci prijaju odmor, čitanje i ozbiljnija pitanja, ona koja obično odložiš jer nemaš vremena.", "Tokom proleća i leta stižu učenje, istraživanje i uvidi. Odgovori dolaze u tišini, više nego kroz napor. Jesen može da razbistri sledeće korake. U poslednjim mesecima taj uvid pretvori u plan, pre nego što stigne aktivna, ambiciozna godina 8."] },
    { title: "Ljubav u godini 7", paras: ["Ljubav postaje tiša i okreće se ka unutra. Parovima možda treba više prostora i dublji razgovori. Ko nema partnera, često bira kvalitet pre količine i može nekog da upozna kroz učenje ili duhovna interesovanja. Lekcija je da svoj unutrašnji svet podeliš, umesto da ga samo čuvaš."] },
    { title: "Stručan rad i novac", paras: ["Povoljni su istraživanje, učenje, pisanje, analiza i stručan rad. Dobra je godina za obuke, sertifikate ili duže odsustvo s posla. Veliko širenje neka sačeka godinu 8. Kad je novac u pitanju, pregled i plan bolji su od kockanja, pa je ovo dobro vreme da na miru pogledaš kuda ti odlazi plata."] },
    { title: "Tišina, san i energija", paras: ["Energija je često tiša. Odmor, priroda, tišina i dobar režim spavanja sada su važni. Jaka je godina za meditaciju, jogu ili obične duge šetnje bez telefona. Pazi na izolaciju, jer nekoliko bliskih ljudi čuva vedru glavu."] },
    { title: "Tri priče o tihom rastu", paras: ["Bankar rođen 15. septembra pohađao je u godini 7 večernje kurseve filozofije. Kaže da je to promenilo način na koji vodi tim.", "Majka dvoje dece počela je svakog jutra da vodi dnevnik i otkrila dugo zakopanu želju da piše. Njena prva priča objavljena je sledeće godine.", "Medicinska sestra iskoristila je godinu 7 da se specijalizuje za palijativnu negu, posle dugog razmišljanja o tome koji joj posao daje najviše smisla."] },
    { title: "Čega se kloniti", paras: ["Ne juri uspeh koji se vidi spolja, godina 7 nagrađuje dubinu. Ne odsecaj se od svih. Ne vrti misli u krug: ono što naučiš treba negde i da primeniš."] },
    { title: "Tihe navike", paras: ["Vodi spisak za čitanje i dnevnik. Svake nedelje provedi malo vremena sam u prirodi, makar u parku. Jednom mesečno postavi sebi veliko pitanje i živi s njim."] },
    { title: "Pitanja za godinu 7", paras: ["U šta stvarno verujem? Šta mi kaže unutrašnji glas kad utihnem? Šta bih učio kad niko ništa ne bi očekivao od mene?"] },
    { title: "Godina 7 u ciklusu", paras: ["U sedmom poglavlju junak se odmara na tihom mestu i razume sve što je prešao. Iskustva iz godina 5 i 6 postaju mudrost. Ta mudrost zatim postaje strategija godine 8 i dar godine 9."] },
    { title: "Dom i tišina", paras: ["Godina 7 kod kuće može da traži više privatnosti i mira. Pomaže tih kutak za čitanje ili razmišljanje, makar fotelja pored prozora. Objasni ukućanima da vreme nasamo ne znači odbacivanje, a zajedničko vreme neka bude ređe, ali mirno i bez žurbe."] },
    { title: "Pet minuta tišine", paras: ["Svake večeri pred spavanje sedi pet minuta u tišini. Postavi jedno pitanje i ne traži odgovor. Tokom meseci mnogi primete da odgovori dolaze sami, u snovima, šetnjama ili razgovorima."] },
    { title: "Pitanje koje čeka", paras: ["Večeras se upitaj: koju istinu izbegavam? Zapiši je, nežno. Ne moraš odmah da reaguješ. Da je vidiš jasno, to je posao godine 7."] },
    { title: "Prijateljstvo u godini 7", paras: ["Prijatelja je manje, ali su veze dublje. Dugi razgovori sa jednom ili dve osobe od poverenja znače više od žurki. Neka prijateljstva prirodno izblede, i to je deo godine."] },
    { title: "Najduhovnija godina", paras: ["Godina 7 je najduhovnija u ciklusu. Mnogi tada otkriju praksu, učitelja ili knjigu koja oblikuje ostatak njihovog života. Ključ je poverenje, a sigurnost ionako niko ne može da ti da."] },
    { title: "Učenje u godini 7", paras: ["Godini 7 prija i praktično učenje. Kurs jezika, studije, stručni sertifikat ili ozbiljno bavljenje hobijem, sve se uklapa, ako te pokreće prava radoznalost, a ne pritisak. Ljudi koji uče u godini 7 često kažu da im znanje ostaje za ceo život. Izaberi jednu temu koja te oduvek privlači, daj joj redovan sat svake nedelje i vidi kuda te vodi. Godina 8 koja sledi često nagradi baš tu veštinu, ponekad na način koji nisi mogao da planiraš."] },
    { title: "Godina 7 i tvoj životni put", paras: ["Za životni put 7 ovo je povratak kući, prirodno vreme učenja i samoće. Za put 3 ili 5 sporiji tempo u početku može da deluje čudno, ali često donosi najoriginalnije ideje iz ciklusa. Za put 8 to je prilika za odmor pre sledećeg napora i za novo razmišljanje o tome kako uspeh treba da izgleda. Za put 2 ili 6 traži vreme nasamo bez osećaja krivice."] },
    { title: "Tihi preokret", paras: ["Preokret često dolazi kao tih uvid: rečenica u knjizi, san, trenutak u šetnji, koji odjednom razjasni sledeći korak."] },
    { title: "Tišina manastira", paras: ["Naši manastiri, od Studenice do Manasije, vekovima su bili mesta tišine, knjiga i razmišljanja. Ne moraš daleko da bi osetio taj mir: dovoljni su jedna sveća, jedna stara knjiga, jedno jutro bez buke. Godina 7 traži baš to."] },
    { title: "Pred godinu 8", paras: ["Pred godinu 8 vredi zapisati šta te je ova godina naučila: koje su se vrednosti izbistrile, koji su ciljevi otpali, koja su se nova pitanja pojavila. Taj spisak, napisan pažljivo i iskreno, služi kao mapa i kompas za ambicioznu godinu koja dolazi. Bez njega snaga godine 8 lako ode u pogrešnom pravcu, a s njim svaki napor ima jasan cilj i svaka odluka se lakše donosi."] },
    { title: "Mirna voda", paras: ["Lična godina 7 je doba mirnog jezera. Pusti da se voda smiri, pogledaj u dubinu i veruj onome što se tamo ogleda."] },
  ],
  "personal-year/8": [
    { title: "Primer: 6. oktobar", paras: ["Pogledajmo rođendan 6. oktobra. U 2026. mesec 10 daje 1, dan daje 6, a godina daje 1. Jedan plus šest plus jedan je osam. Ovoj osobi je 2026. lična godina 8, godina žetve, moći i rezultata."] },
    { title: "Od prvih ciljeva do jesenjih odluka", paras: ["Godina 8 često počinje ambicijom. Posle razmišljanja iz godine 7 osećaš da si spreman da postupiš po onome što si naučio. Početak godine je dobar za jasne ciljeve i za to da potražiš ono što zaslužuješ.", "Prolećne i letnje mesece obeležavaju prilike: unapređenja, ugovori, ulaganja, priznanja. Trud iz prethodnih godina počinje da se isplaćuje. Jesen može da donese velike odluke o novcu i autoritetu. Pred kraj godine učvrsti dobijeno i spremi se da pustiš ono što neće pristajati uz godinu 9."] },
    { title: "Ljubav u godini 8", paras: ["Ljubav može da postane partnerstvo jednakih. Parovi donose velike zajedničke odluke, kao što su kupovina stana ili zajednička firma. Oni bez partnera često privlače samouverene i sposobne ljude. Rizik je da posao istisne nežnost, pa čuvajte vreme jedno za drugo."] },
    { title: "Karijera i novac", paras: ["Numerologija ovu godinu čita kao najjaču u ciklusu za karijeru i finansije. Zatraži povišicu, izbaci proizvod na tržište, potpiši ugovor, prihvati vodeću ulogu. Ishod ti niko ne može obećati, ali ako si dugo čekao da pitaš, ovo je godina za to. Rezultati zavise od temelja iz godina 4 do 7, pa su iskrenost i dobro planiranje neophodni. Pazi na poreze, ugovore i pošten odnos prema drugima."] },
    { title: "Snaga, stres i san", paras: ["Snage ima, ali i stres može da bude veliki. Redovno vežbanje, trening snage i dobar san podržavaju tempo. Ako se i u krevetu vrtiš oko sutrašnjeg sastanka, vreme je da malo spustiš loptu. Pazi na premor i na naviku da svoju vrednost meriš samo rezultatima."] },
    { title: "Tri priče o žetvi", paras: ["Advokatica rođena 6. oktobra postala je u godini 8 partnerka u svojoj kancelariji, posle godina strpljivog rada.", "Stolar je konačno podigao cene u skladu sa svojom veštinom. Prihod mu se udvostručio, a i klijenti su mu bolji.", "Nastavnica je iskoristila godinu 8 da objavi udžbenik koji je godinama pisala. Danas se koristi širom zemlje."] },
    { title: "Zamke uspeha", paras: ["Kloni se pohlepe i prečica. Ne kontroliši druge. Ne zapostavljaj zdravlje i porodicu u trci za uspehom."] },
    { title: "Navike koje drže pravac", paras: ["Postavi tri jasna cilja za godinu i proveravaj ih svakog meseca. Pažljivo prati novac, od plate do poslednjeg fiskalnog računa. Slavi pobede i podeli ih sa ljudima koji su ti pomogli."] },
    { title: "Pitanja za godinu 8", paras: ["Šta za mene stvarno znači uspeh? Šta imam hrabrosti da zatražim? Kako da svoju moć koristim kako valja?"] },
    { title: "Godina 8 u ciklusu", paras: ["Osmo poglavlje je ono u kom junak dobija nagradu. Seme iz godine 1 sada je drvo, a plod je zreo. Ono što sada bereš zavisi od toga kako si sadio, negovao i učio. Godina 9 će tražiti da deo toga podeliš i pustiš."] },
    { title: "Dom i novac", paras: ["Veći stan, renoviranje ili nova finansijska sigurnost mogu da stignu baš u godini 8. Razgovaraj otvoreno o novcu sa porodicom i pazi da ambicije budu zajedničke, a ne nametnute. Deci koristi kad vide da se trud nagrađuje."] },
    { title: "Mesečni zapis", paras: ["Na kraju svakog meseca zapiši jedno dostignuće i jednu osobu koja ti je pomogla da do njega stigneš. Kad se godina završi, imaćeš zapis i o uspehu i o zahvalnosti, a to te čuva da te moć ne ponese."] },
    { title: "Gde tražiš premalo", paras: ["Pitaj se: gde još uvek tražim premalo? Izaberi jednu oblast, cenu, platu, granicu, i odluči šta stvarno zaslužuješ. Zatim napravi jedan korak ka tome da to i zatražiš."] },
    { title: "Prijateljstvo u godini 8", paras: ["Novi kontakti dolaze preko posla i uticaja. Drži stare prijatelje blizu, oni te podsećaju kakav je život bio pre uspeha. Kad nekom odvojiš vreme ili priskočiš u pomoć, to učvršćuje vezu više od skupog poklona."] },
    { title: "Novac i duh", paras: ["Iznutra, godina 8 uči da materijalni i duhovni život nisu neprijatelji. Kad novac i moć koristiš pošteno, i to je duhovna praksa. Ključ je ravnoteža: ambicija s ljubaznošću, snaga s poniznošću."] },
    { title: "Pravedna moć", paras: ["Godina 8 je i test pravednosti. Kako se ponašaš prema kolegama, klijentima i konkurentima kad imaš prednost, to godinama oblikuje tvoj ugled. Plaćaj ljude dobro, priznaj im rad i drži obećanja, čak i mala. Mnogi numerolozi kažu da 8 nagrađuje integritet i ispravlja pohlepu, a iskustvo se često slaže: pošteni dogovori opstaju, dok se prečice u godini 9 vraćaju kao trošak. Kad se moć koristi blago, pretvara se u poverenje, a poverenje je najtrajnija žetva."] },
    { title: "Godina 8 i tvoj životni put", paras: ["Za životni put 8 ovo je vrhunac moći i odgovornosti. Za put 2 ili 6 može biti neprijatno da preuzmeš autoritet, a ovo je baš godina za to. Za put 7 uspeh često dolazi preko stručnosti, ne preko sile. Za put 3 stvaralački rad konačno može da donese novac. Za put 1 to je godina kad drugi prepoznaju tvoje vođstvo."] },
    { title: "Trenutak priznanja", paras: ["Preokret često dolazi kao trenutak priznanja: ponuda, nagrada, rezultat koji potvrdi godine truda. Prihvati ga celog, bez lažne skromnosti."] },
    { title: "Moba", paras: ["Kod nas se na selu za žetvu skupljala moba: komšije i rod dođu da pomognu bez novca, a domaćin ih na kraju dana nahrani za velikim stolom. Godina 8 ponavlja tu mudrost: žetva je najslađa kad se podeli."] },
    { title: "Pred godinu 9", paras: ["Pred godinu 9 vredi napraviti miran pregled: šta od postignutog želiš da zadržiš, a šta je već odigralo svoju ulogu. To olakšava završno poglavlje. Mnogi u kasnu jesen godine 8 odluče da poklone, predaju ili zatvore nešto, pa godinu 9 počnu lakše i mirnije."] },
    { title: "Na kraju žetve", paras: ["Lična godina 8 je doba žetve. Sakupi zarađeno sa zahvalnošću, podeli velikodušno i ponesi tu snagu u završno poglavlje ciklusa."] },
  ],
  "personal-year/9": [
    { title: "Primer: 17. septembar", paras: ["Neko ko je rođen 17. septembra zatvara krug u 2026. Mesec daje 9, dan 17 daje 8, a godina daje 1. Devet plus osam plus jedan je osamnaest, što se svodi na 9. Zato je 2026. toj osobi lična godina 9, završna godina ciklusa, a 2027. će biti nova lična godina 1."] },
    { title: "Zatvaranje, mesec za mesecom", paras: ["Godina 9 često počinje završecima. Projekti, veze i navike kojima je vreme prošlo zatvaraju se sami od sebe. U prvim mesecima osvrni se na poslednjih devet godina i vidi šta je zaokruženo.", "Proleće i leto su vreme puštanja: raščišćavanje kuće, završavanje starih poslova, praštanje. Jesen je često emotivna, puna uspomena i rastanaka. Poslednji meseci su pauza pred novi početak godine 1, vreme za odmor i poverenje."] },
    { title: "Ljubav u godini 9", paras: ["Ove godine se vidi koliko je koja veza duboka. Neke se završavaju nežno, druge se obnavljaju na mudrijoj osnovi. Ako nemaš partnera, pametno je da prvo zalečiš stare rane pa tek onda počneš nešto ozbiljno, a nova ljubav često stiže u sledećoj godini 1. Saosećanje i praštanje su ovde ključni."] },
    { title: "Završni poslovi i novac", paras: ["Ovo je godina za završavanje, a početke ostavi za kasnije. Privedi projekte kraju, zatvori račune, predaj uloge i sredi finansije. Posebno ispunjava rad koji pomaže drugima: nastava, humanitarni rad, lečenje, umetnost. Velike poslovne poteze odloži do godine 1."] },
    { title: "Odmor i stare navike", paras: ["Energije može biti manje, a osećanja dolaze u talasima. Pomažu odmor, blago vežbanje i vreme u prirodi. Mnogima je u godini 9 lakše nego ikad da se oslobode starih navika, kao što su pušenje ili preterivanje s poslom."] },
    { title: "Tri priče o kraju i olakšanju", paras: ["Čovek rođen 17. septembra zatvorio je u godini 9 firmu koju je vodio dvanaest godina. U godini 1 otvorio je manju, u kojoj je srećniji.", "Žena je u godini 9 oprostila sestri sa kojom godinama nije razgovarala. Sledeće leto su provele zajedno, prvi put posle jedne decenije.", "Jedna porodica je u godini 9 raščistila tavan i poklonila polovinu stvari. Kažu da kuća sada diše."] },
    { title: "Šta ne treba vući dalje", paras: ["Ne drži se za ono što se završava. Ne preuzimaj prerano velike nove obaveze. Ne daj gorčini da se uvuče, jer zahvalnost čini prelaz lakšim."] },
    { title: "Vežbe puštanja", paras: ["Svakog meseca raščisti po jednu fioku, plakar ili sobu. Piši pisma zahvalnosti ili oproštaja, svejedno da li ćeš ih poslati. Pokloni ono što ti više ne treba."] },
    { title: "Pitanja za godinu 9", paras: ["Šta je u mom životu zaokruženo? Šta mogu da oprostim? Šta želim da ponesem u sledeći ciklus, a šta mogu da ostavim?"] },
    { title: "Godina 9 u ciklusu", paras: ["Deveto poglavlje je poslednje: junak gleda unazad, zahvaljuje i pušta. Sve što je počelo u godini 1 stiže do svog kraja ili do svoje promene. Prostor koji se sada oslobodi postaje njiva za sledeće seme."] },
    { title: "Dom, uspomene i pomirenje", paras: ["Godina 9 u kući može da znači selidbu, decu koja odlaze, raščišćavanje i porodična okupljanja. To je nežna godina za pomirenje. Podelite uspomene, gledajte zajedno stare fotografije i odajte poštovanje onome što je porodica preživela."] },
    { title: "Jedan list papira", paras: ["Jedne tihe večeri zapiši na jedan list najvažnije lekcije poslednjih devet godina. Pročitaj ih naglas, zahvali svakoj godini, a onda presavij list i skloni ga. Mnogi kažu da ova jednostavna ceremonija donosi dubok mir."] },
    { title: "Šta držiš iz straha", paras: ["Pre spavanja se pitaj: čega se držim iz straha, a ne iz ljubavi? Imenuj jednu stvar. Zamisli kako je nežno puštaš. Ako ti to zvuči ispravno, napravi prvi korak ove nedelje."] },
    { title: "Prijateljstvo u godini 9", paras: ["Neka prijateljstva se prirodno završavaju, druga prerastaju u veze za ceo život. Zahvali ljudima koji su išli s tobom kroz ovaj ciklus, makar jednom porukom."] },
    { title: "Saosećanje i zaokruživanje", paras: ["Iznutra, godina 9 je u znaku saosećanja i zaokruživanja. Mnogi osećaju jaču želju da pomognu drugima, da služe nekom cilju ili da stvore nešto značajno. Kad nešto pustiš, pravi se mesto za ono što tek treba da dođe."] },
    { title: "Služenje i davanje", paras: ["Godina 9 je i vreme služenja. Mnoge privlače volontiranje, mentorstvo nekom mlađem ili podrška cilju do kog im je stalo. Takvo davanje ublažava tugu zbog završetaka i daje godini smisao. Nisu potrebni veliki gestovi: da naučiš komšiju nekoj veštini, pomogneš u lokalnom prihvatilištu ili podeliš iskustvo s nekim ko tek počinje, sve se računa. Ono što daješ bez računice ostaje u ljudima i kad krene novi ciklus."] },
    { title: "Godina 9 i tvoj životni put", paras: ["Za životni put 9 ovo je snažna, ponekad emotivna godina zaokruživanja. Za put 1 ili 8 puštanje može biti teško, jer kontrola deluje sigurnije. Za put 6 može da uključi rastanke u porodici, obavljene s velikom nežnošću. Za put 4 to je prilika da se raščiste strukture koje su postale previše krute, i da se napravi mesta za lakši novi početak."] },
    { title: "Tihi rastanak", paras: ["Preokret često dolazi kao tih rastanak, kraj nečeg važnog, posle kog sledi neočekivan osećaj slobode i lakoće."] },
    { title: "Čišćenje pred praznik", paras: ["Kod nas se pred slavu i velike praznike kuća čisti od podruma do tavana, a na Bele poklade, pred Uskršnji post, ljudi jedni od drugih traže oproštaj rečima „oprosti mi”. Godina 9 je takav veliki praznik ciklusa: čisti se, prašta se i sprema mesto za novo."] },
    { title: "Pred novu godinu 1", paras: ["Pred novu godinu 1 vredi ostaviti malo praznog prostora: nekoliko nedelja bez novih obaveza i velikih odluka, samo odmor i slušanje. Iz te tišine često se rodi jasna namera za sledeći ciklus. Ne žuri da popuniš prazninu, ona je priprema. Novo seme traži čistu i odmornu zemlju."] },
    { title: "Poslednja slika", paras: ["Lična godina 9 je doba opalog lišća. Pusti ga sa zahvalnošću, odmori se u tišini i veruj da novo proleće već čeka pod zemljom."] },
  ],
};
